window.QURAN_TAFSIRS = window.QURAN_TAFSIRS || {};
window.QURAN_TAFSIRS["saadi"] = {"1":{"1":"{ بِسْمِ اللَّهِ } أي: أبتدئ بكل اسم لله تعالى, لأن لفظ { اسم } مفرد مضاف, فيعم جميع الأسماء [الحسنى]. { اللَّهِ } هو المألوه المعبود, المستحق لإفراده بالعبادة, لما اتصف به من صفات الألوهية وهي صفات الكمال. { الرَّحْمَنِ الرَّحِيمِ } اسمان دالان على أنه تعالى ذو الرحمة الواسعة العظيمة التي وسعت كل شيء, وعمت كل حي, وكتبها للمتقين المتبعين لأنبيائه ورسله. فهؤلاء لهم الرحمة المطلقة, ومن عداهم فلهم نصيب منها. واعلم أن من القواعد المتفق عليها بين سلف الأمة وأئمتها, الإيمان بأسماء الله وصفاته, وأحكام الصفات. فيؤمنون مثلا, بأنه رحمن رحيم, ذو الرحمة التي اتصف بها, المتعلقة بالمرحوم. فالنعم كلها, أثر من آثار رحمته, وهكذا في سائر الأسماء. يقال في العليم: إنه عليم ذو علم, يعلم [به] كل شيء, قدير, ذو قدرة يقدر على كل شيء.","2":"{ الْحَمْدُ لِلَّهِ } [هو] الثناء على الله بصفات الكمال, وبأفعاله الدائرة بين الفضل والعدل, فله الحمد الكامل, بجميع الوجوه. { رَبِّ الْعَالَمِينَ } الرب, هو المربي جميع العالمين -وهم من سوى الله- بخلقه إياهم, وإعداده لهم الآلات, وإنعامه عليهم بالنعم العظيمة, التي لو فقدوها, لم يمكن لهم البقاء. فما بهم من نعمة, فمنه تعالى. وتربيته تعالى لخلقه نوعان: عامة وخاصة. فالعامة: هي خلقه للمخلوقين, ورزقهم, وهدايتهم لما فيه مصالحهم, التي فيها بقاؤهم في الدنيا. والخاصة: تربيته لأوليائه, فيربيهم بالإيمان, ويوفقهم له, ويكمله لهم, ويدفع عنهم الصوارف, والعوائق الحائلة بينهم وبينه, وحقيقتها: تربية التوفيق لكل خير, والعصمة عن كل شر. ولعل هذا [المعنى] هو السر في كون أكثر أدعية الأنبياء بلفظ الرب. فإن مطالبهم كلها داخلة تحت ربوبيته الخاصة. فدل قوله { رَبِّ الْعَالَمِينَ } على انفراده بالخلق والتدبير, والنعم, وكمال غناه, وتمام فقر العالمين إليه, بكل وجه واعتبار.","3":"اسمان دالان على أنه تعالى ذو الرحمة الواسعة العظيمة التي وسعت كل شيء، وعمت كل حي، وكتبها للمتقين المتبعين لأنبيائه ورسله. فهؤلاء لهم الرحمة المطلقة، ومن عداهم فلهم نصيب منها.","4":"{ مَالِكِ يَوْمِ الدِّينِ } المالك: هو من اتصف بصفة الملك التي من آثارها أنه يأمر وينهى, ويثيب ويعاقب, ويتصرف بمماليكه بجميع أنواع التصرفات, وأضاف الملك ليوم الدين, وهو يوم القيامة, يوم يدان الناس فيه بأعمالهم, خيرها وشرها, لأن في ذلك اليوم, يظهر للخلق تمام الظهور, كمال ملكه وعدله وحكمته, وانقطاع أملاك الخلائق. حتى [إنه] يستوي في ذلك اليوم, الملوك والرعايا والعبيد والأحرار. كلهم مذعنون لعظمته, خاضعون لعزته, منتظرون لمجازاته, راجون ثوابه, خائفون من عقابه, فلذلك خصه بالذكر, وإلا, فهو المالك ليوم الدين ولغيره من الأيام.","5":"وقوله { إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ } أي: نخصك وحدك بالعبادة والاستعانة, لأن تقديم المعمول يفيد الحصر, وهو إثبات الحكم للمذكور, ونفيه عما عداه. فكأنه يقول: نعبدك, ولا نعبد غيرك, ونستعين بك, ولا نستعين بغيرك. وقدم العبادة على الاستعانة, من باب تقديم العام على الخاص, واهتماما بتقديم حقه تعالى على حق عبده. و { العبادة } اسم جامع لكل ما يحبه الله ويرضاه من الأعمال, والأقوال الظاهرة والباطنة. و { الاستعانة } هي الاعتماد على الله تعالى في جلب المنافع, ودفع المضار, مع الثقة به في تحصيل ذلك. والقيام بعبادة الله والاستعانة به هو الوسيلة للسعادة الأبدية, والنجاة من جميع الشرور, فلا سبيل إلى النجاة إلا بالقيام بهما. وإنما تكون العبادة عبادة, إذا كانت مأخوذة عن رسول الله صلى الله عليه وسلم مقصودا بها وجه الله. فبهذين الأمرين تكون عبادة, وذكر { الاستعانة } بعد { العبادة } مع دخولها فيها, لاحتياج العبد في جميع عباداته إلى الاستعانة بالله تعالى. فإنه إن لم يعنه الله, لم يحصل له ما يريده من فعل الأوامر, واجتناب النواهي.","6":"ثم قال تعالى: { اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ } أي: دلنا وأرشدنا, ووفقنا للصراط المستقيم, وهو الطريق الواضح الموصل إلى الله, وإلى جنته, وهو معرفة الحق والعمل به, فاهدنا إلى الصراط واهدنا في الصراط. فالهداية إلى الصراط: لزوم دين الإسلام, وترك ما سواه من الأديان, والهداية في الصراط, تشمل الهداية لجميع التفاصيل الدينية علما وعملا. فهذا الدعاء من أجمع الأدعية وأنفعها للعبد ولهذا وجب على الإنسان أن يدعو الله به في كل ركعة من صلاته, لضرورته إلى ذلك.","7":"وهذا الصراط المستقيم هو: { صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ } من النبيين والصديقين والشهداء والصالحين. { غَيْرِ } صراط { الْمَغْضُوبِ عَلَيْهِمْ } الذين عرفوا الحق وتركوه كاليهود ونحوهم. وغير صراط { الضَّالِّينَ } الذين تركوا الحق على جهل وضلال, كالنصارى ونحوهم."},"78":{"1":"أي: عن أي شيء يتساءل المكذبون بآيات الله؟","2":"ثم بين ما يتساءلون عنه فقال: { عَنِ النَّبَإِ الْعَظِيمِ]","3":"[الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ } أي: عن الخبر العظيم الذي طال فيه نزاعهم، وانتشر فيه خلافهم على وجه التكذيب والاستبعاد، وهو النبأ الذي لا يقبل الشك ولا يدخله الريب، ولكن المكذبون بلقاء ربهم لا يؤمنون، ولو جاءتهم كل آية حتى يروا العذاب الأليم.","4":"{ كَلَّا سَيَعْلَمُونَ ثُمَّ كَلَّا سَيَعْلَمُونَ } أي: سيعلمون إذا نزل بهم العذاب ما كانوا به يكذبون، حين يدعون إلى نار جهنم دعا، ويقال لهم: { هَذِهِ النَّارُ الَّتِي كُنْتُمْ بِهَا تُكَذِّبُونَ }","5":4,"6":"أي: أما أنعمنا عليكم بنعم جليلة، فجعلنا لكم { الْأَرْضَ مِهَادًا } أي: ممهدة مهيأة لكم ولمصالحكم، من الحروث والمساكن والسبل.","7":"{ وَالْجِبَالَ أَوْتَادًا } تمسك الأرض لئلا تضطرب بكم وتميد.","8":"{ وَخَلَقْنَاكُمْ أَزْوَاجًا } أي: ذكورا وإناثا من جنس واحد، ليسكن كل منهما إلى الآخر، فتكون المودة والرحمة، وتنشأ عنهما الذرية، وفي ضمن هذا الامتنان، بلذة المنكح.","9":"{ وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا } أي: راحة لكم، وقطعا لأشغالكم، التي متى تمادت بكم أضرت بأبدانكم،","10":"فجعل الله الليل والنوم يغشى الناس لتنقطع حركاتهم الضارة، وتحصل راحتهم النافعة.","11":10,"12":"{ وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا } أي: سبع سموات، في غاية القوة، والصلابة والشدة، وقد أمسكها الله بقدرته، وجعلها سقفا للأرض، فيها عدة منافع لهم، ولهذا ذكر من منافعها الشمس فقال: { وَجَعَلْنَا سِرَاجًا وَهَّاجًا }","13":"نبه بالسراج على النعمة بنورها، الذي صار كالضرورة للخلق، وبالوهاج الذي فيه الحرارة على حرارتها وما فيها من المصالح","14":"{ وَأَنْزَلْنَا مِنَ الْمُعْصِرَاتِ } أي: السحاب { مَاءً ثَجَّاجًا } أي: كثيرا جدا.","15":"{ لِنُخْرِجَ بِهِ حَبًّا } من بر وشعير وذرة وأرز، وغير ذلك مما يأكله الآدميون.{ وَنَبَاتًا } يشمل سائر النبات، الذي جعله الله قوتا لمواشيهم.","16":"{ وَجَنَّاتٍ أَلْفَافًا } أي: بساتين ملتفة، فيها من جميع أصناف الفواكه اللذيذة.فالذي أنعم عليكم بهذه النعم العظيمة ، التي لا يقدر قدرها، ولا يحصى عددها، كيف [تكفرون به و] تكذبون ما أخبركم به من البعث والنشور؟! أم كيف تستعينون بنعمه على معاصيه وتجحدونها؟\\\"","17":"ذكر تعالى ما يكون في يوم القيامة الذي يتساءل عنه المكذبون، ويجحده المعاندون، أنه يوم عظيم، وأن الله جعله { مِيقَاتًا } للخلق.","18":"{ يُنْفَخُ فِي الصُّورِ فَتَأْتُونَ أَفْوَاجًا } ويجري فيه من الزعازع والقلاقل ما يشيب له الوليد، وتنزعج له القلوب،","19":"وتشقق السماء حتى تكون أبوابا","20":"فتسير الجبال، حتى تكون كالهباء المبثوث، ، ويفصل الله بين الخلائق بحمكه الذي لا يجور،","21":"وتوقد نار جهنم التي أرصدها الله وأعدها للطاغين، وجعلها مثوى لهم ومآبا","22":"وتوقد نار جهنم التي أرصدها الله وأعدها للطاغين، وجعلها مثوى لهم ومآبا ،","23":"وأنهم يلبثون فيها أحقابا كثيرة و { الحقب } على ما قاله كثير من المفسرين: ثمانون سنة.","24":"وهم إذا وردوها { لَا يَذُوقُونَ فِيهَا بَرْدًا وَلَا شَرَابًا } أي: لا ما يبرد جلودهم، ولا ما يدفع ظمأهم.","25":"{ إِلَّا حَمِيمًا } أي: ماء حارا، يشوي وجوههم، ويقطع أمعاءهم، { وَغَسَّاقًا } وهو: صديد أهل النار، الذي هو في غاية النتن، وكراهة المذاق،","26":"استحقوا هذه العقوبات الفظيعة جزاء لهم ووفاقا على ما عملوا من الأعمال الموصلة إليها، لم يظلمهم الله، ولكن ظلموا أنفسهم،","27":"وذكر أعمالهم، التي استحقوا بها هذا الجزاء، فقال: { إِنَّهُمْ كَانُوا لَا يَرْجُونَ حِسَابًا } أي: لا يؤمنون بالبعث، ولا أن الله يجازي الخلق بالخير والشر، فلذلك أهملوا العمل للآخرة.","28":"{ وَكَذَّبُوا بِآيَاتِنَا كِذَّابًا } أي: كذبوا بها تكذيبا واضحا صريحا وجاءتهم البينات فعاندوها.","29":"{ وَكُلُّ شَيْءٍ } من قليل وكثير، وخير وشر { أَحْصَيْنَاهُ كِتَابًا } أي: كتبناه في اللوح المحفوظ، فلا يخشى المجرمون أنا عذبناهم بذنوب لم يعملوها، ولا يحسبوا أنه يضيع من أعمالهم شيء، أو ينسى منها مثقال ذرة، كما قال تعالى: { وَوُضِعَ الْكِتَابُ فَتَرَى الْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَا وَيْلَتَنَا مَالِ هَذَا الْكِتَابِ لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً إِلَّا أَحْصَاهَا وَوَجَدُوا مَا عَمِلُوا حَاضِرًا وَلَا يَظْلِمُ رَبُّكَ أَحَدًا }","30":"{ فَذُوقُوا } أيها المكذبون هذا العذاب الأليم والخزي الدائم { فَلَنْ نَزِيدَكُمْ إِلَّا عَذَابًا } وكل وقت وحين يزداد عذابهم [وهذه الآية أشد الآيات في شدة عذاب أهل النار أجارنا الله منها].","31":"لما ذكر حال المجرمين ذكر مآل المتقين فقال: { إِنَّ لِلْمُتَّقِينَ مَفَازًا } أي: الذين اتقوا سخط ربهم، بالتمسك بطاعته، والانكفاف عما يكرهه فلهم مفاز ومنجي، وبعد عن النار.","32":"وفي ذلك المفاز لهم { حَدَائِقَ } وهي البساتين الجامعة لأصناف الأشجار الزاهية، في الثمار التي تتفجر بين خلالها الأنهار، وخص الأعناب لشرفها وكثرتها في تلك الحدائق.","33":"ولهم فيها زوجات على مطالب النفوس { كَوَاعِبَ } وهي: النواهد اللاتي لم تتكسر ثديهن من شبابهن، وقوتهن ونضارتهن .{ والأَتْرَاب } اللاتي على سن واحد متقارب، ومن عادة الأتراب أن يكن متآلفات متعاشرات، وذلك السن الذي هن فيه ثلاث وثلاثون سنة، في أعدل سن الشباب .","34":"{ وَكَأْسًا دِهَاقًا } أي: مملوءة من رحيق، لذة للشاربين،","35":"{ لَا يَسْمَعُونَ فِيهَا لَغْوًا } أي: كلاما لا فائدة فيه { وَلَا كِذَّابًا } أي: إثما.كما قال تعالى: { لَا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا تَأْثِيمًا إِلَّا قِيلًا سَلَامًا سَلَامًا }","36":"وإنما أعطاهم الله هذا الثواب الجزيل [من فضله وإحسانه]. { جَزَاءً مِنْ رَبِّكَ } لهم { عَطَاءً حِسَابًا } أي: بسبب أعمالهم التي وفقهم الله لها، وجعلها ثمنا لجنته ونعيمها .","37":"أي: الذي أعطاهم هذه العطايا هو ربهم { رَبُّ السَّمَاوَاتِ وَالْأَرْضِ } الذي خلقها ودبرها { الرَّحْمَنِ } الذي رحمته وسعت كل شيء، فرباهم ورحمهم، ولطف بهم، حتى أدركوا ما أدركوا.ثم ذكر عظمته وملكه العظيم يوم القيامة، وأن جميع الخلق كلهم ذلك اليوم ساكتون لا يتكلمون و { لَا يَمْلِكُونَ مِنْهُ خِطَابًا } إلا من أذن له الرحمن وقال صوابا، فلا يتكلم أحد إلا بهذين الشرطين: أن يأذن الله له في الكلام، وأن يكون ما تكلم به صوابا، لأن { ذَلِكَ الْيَوْمُ } هو { الْحَقُّ } الذي لا يروج فيه الباطل، ولا ينفع فيه الكذب","38":"وفي ذلك اليوم { يَقُومُ الرُّوحُ } وهو جبريل عليه السلام، الذي هو أشرف الملائكة { وَالْمَلَائِكَةِ } [أيضا يقوم الجميع] { صَفًّا } خاضعين لله { لَا يَتَكَلَّمُونَ } إلا بما أذن لهم الله به .","39":"فلما رغب ورهب، وبشر وأنذر، قال: { فَمَنْ شَاءَ اتَّخَذَ إِلَى رَبِّهِ مَآبًا } أي: عملا، وقدم صدق يرجع إليه يوم القيامة.","40":"{ إِنَّا أَنْذَرْنَاكُمْ عَذَابًا قَرِيبًا } لأنه قد أزف مقبلا، وكل ما هو آت فهو قريب.{ يَوْمَ يَنْظُرُ الْمَرْءُ مَا قَدَّمَتْ يَدَاهُ } أي: هذا الذي يهمه ويفزع إليه، فلينظر في هذه الدنيا إليه ، كما قال تعالى: { يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ } الآيات.فإن وجد خيرا فليحمد الله، وإن وجد غير ذلك فلا يلومن إلا نفسه، ولهذا كان الكفار يتمنون الموت من شدة الحسرة والندم.نسأل الله أن يعافينا من الكفر والشر كله، إنه جواد كريم.تم تفسير سورة عم، والحمد لله رب العالمين"},"79":{"1":"هذه الإقسامات بالملائكة الكرام، وأفعالهم الدالة على كمال انقيادهم لأمر الله، وإسراعهم في تنفيذ أمره، يحتمل أن المقسم عليه، الجزاء والبعث، بدليل الإتيان بأحوال القيامة بعد ذلك، ويحتمل أن المقسم عليه والمقسم به متحدان، وأنه أقسم على الملائكة، لأن الإيمان بهم أحد أركان الإيمان الستة، ولأن في ذكر أفعالهم هنا ما يتضمن الجزاء الذي تتولاه الملائكة عند الموت وقبله وبعده، فقال: { وَالنَّازِعَاتِ غَرْقًا } وهم الملائكة التي تنزع الأرواح بقوة، وتغرق في نزعها حتى تخرج الروح، فتجازى بعملها.","2":"{ وَالنَّاشِطَاتِ نَشْطًا } وهم الملائكة أيضا، تجتذب الأرواح بقوة ونشاط، أو أن النزع يكون لأرواح المؤمنين، والنشط لأرواح الكفار.","3":"{ وَالسَّابِحَاتِ } أي: المترددات في الهواء صعودا ونزولا { سَبْحًا }","4":"{ فَالسَّابِقَاتِ } لغيرها { سَبْقًا } فتبادر لأمر الله، وتسبق الشياطين في إيصال الوحي إلى رسل الله حتى لا تسترقه .","5":"{ فَالْمُدَبِّرَاتِ أَمْرًا } الملائكة، الذين وكلهم الله أن يدبروا كثيرا من أمور العالم العلوي والسفلي، من الأمطار، والنبات، والأشجار، والرياح، والبحار، والأجنة، والحيوانات، والجنة، والنار [وغير ذلك].","6":"{ يَوْمَ تَرْجُفُ الرَّاجِفَةُ } وهي قيام الساعة،","7":"{ تَتْبَعُهَا الرَّادِفَةُ } أي: الرجفة الأخرى التي تردفها وتأتي تلوها،","8":"{ قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ } أي: موجفة ومنزعجة من شدة ما ترى وتسمع.","9":"{ أَبْصَارُهَا خَاشِعَةٌ } أي: ذليلة حقيرة، قد ملك قلوبهم الخوف، وأذهل أفئدتهم الفزع، وغلب عليهم التأسف [واستولت عليهم] الحسرة.","10":9,"11":"يقولون أي: الكفار في الدنيا، على وجه التكذيب: { أَئِذَا كُنَّا عِظَامًا نَخِرَةً } أي: بالية فتاتا.","12":"{ قَالُوا تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ } أي: استبعدوا أن يبعثهم الله ويعيدهم بعدما كانوا عظاما نخرة، جهلا [منهم] بقدرة الله، وتجرؤا عليه.","13":"قال الله في بيان سهولة هذا الأمر عليه: { فَإِنَّمَا هِيَ زَجْرَةٌ وَاحِدَةٌ } ينفخ فيها في الصور.","14":"فإذا الخلائق كلهم { بِالسَّاهِرَةِ } أي: على وجه الأرض، قيام ينظرون، فيجمعهم الله ويقضي بينهم بحكمه العدل ويجازيهم.","15":"يقول الله تعالى لنبيه محمد صلى الله عليه وسلم: { هَلْ أتَاكَ حَدِيثُ مُوسَى } وهذا الاستفهام عن أمر عظيم متحقق وقوعه.","16":"أي: هل أتاك حديثه { إِذْ نَادَاهُ رَبُّهُ بِالْوَادِي الْمُقَدَّسِ طُوًى } وهو المحل الذي كلمه الله فيه، وامتن عليه بالرسالة، واختصه بالوحي والاجتباء","17":"{ اذْهَبْ إِلَى فِرْعَوْنَ إِنَّهُ طَغَى } أي: فانهه عن طغيانه وشركه وعصيانه، بقول لين، وخطاب لطيف، لعله { يتذكر أو يخشى }","18":"{ فَقُلْ } له: { هَلْ لَكَ إِلَى أَنْ تَزَكَّى } أي: هل لك في خصلة حميدة، ومحمدة جميلة، يتنافس فيها أولو الألباب، وهي أن تزكي نفسك وتطهرها من دنس الكفر والطغيان، إلى الإيمان والعمل الصالح؟","19":"{ وَأَهْدِيَكَ إِلَى رَبِّكَ } أي: أدلك عليه، وأبين لك مواقع رضاه، من مواقع سخطه. { فَتَخْشَى } الله إذا علمت الصراط المستقيم، فامتنع فرعون مما دعاه إليه موسى.","20":"{ فَأَرَاهُ الْآيَةَ الْكُبْرَى } أي: جنس الآية الكبرى، فلا ينافي تعددها { فَأَلْقَى عَصَاهُ فَإِذَا هِيَ ثُعْبَانٌ مُبِينٌ وَنَزَعَ يَدَهُ فَإِذَا هِيَ بَيْضَاءُ لِلنَّاظِرِينَ }","21":"{ فَكَذَّبَ } بالحق { وَعَصَى } الأمر،","22":"{ ثُمَّ أَدْبَرَ يَسْعَى } أي: يجتهد في مبارزة الحق ومحاربته،","23":"{ فَحَشَرَ } جنوده أي: جمعهم { فَنَادَى}","24":"[ فَقَالَ } لهم: { أَنَا رَبُّكُمُ الْأَعْلَى } فأذعنوا له وأقروا بباطله حين استخفهم،","25":"{ فَأَخَذَهُ اللَّهُ نَكَالَ الْآخِرَةِ وَالْأُولَى } أي: صارت عقوبته دليلا وزاجرا، ومبينة لعقوبة الدنيا والآخرة،","26":"{ إِنَّ فِي ذَلِكَ لَعِبْرَةً لِمَنْ يَخْشَى } فإن من يخشى الله هو الذي ينتفع بالآيات والعبر، فإذا رأى عقوبة فرعون، عرف أن كل من تكبر وعصى، وبارز الملك الأعلى، عاقبه في الدنيا والآخرة، وأما من ترحلت خشية الله من قلبه، فلو جاءته كل آية لم يؤمن [بها].","27":"يقول تعالى مبينا دليلا واضحا لمنكري البعث ومستبعدي إعادة الله للأجساد: { أَأَنْتُمْ } أيها البشر { أَشَدُّ خَلْقًا أَمِ السَّمَاءُ } ذات الجرم العظيم، والخلق القوي، والارتفاع الباهر { بَنَاهَا } الله.","28":"{ رَفَعَ سَمْكَهَا } أي: جرمها وصورتها، { فَسَوَّاهَا } بإحكام وإتقان يحير العقول، ويذهل الألباب،","29":"{ وَأَغْطَشَ لَيْلَهَا } أي: أظلمه، فعمت الظلمة [جميع] أرجاء السماء، فأظلم وجه الأرض، { وَأَخْرَجَ ضُحَاهَا } أي: أظهر فيه النور العظيم، حين أتى بالشمس، فامتد الناس في مصالح دينهم ودنياهم.","30":"{ وَالْأَرْضَ بَعْدَ ذَلِكَ } أي: بعد خلق السماء { دَحَاهَا } أي: أودع فيها منافعها.","31":"* أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا","32":"{ وَالْجِبَالَ أَرْسَاهَا } أي: ثبتها في الأرض. فدحى الأرض بعد خلق السماء، كما هو نص هذه الآيات [الكريمة]. وأما خلق نفس الأرض، فمتقدم على خلق السماء كما قال تعالى: { قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِالَّذِي خَلَقَ الْأَرْضَ فِي يَوْمَيْنِ } إلى أن قال: { ثُمَّ اسْتَوَى إِلَى السَّمَاءِ وهي دخان فقال لها وللأرض ائتنا طوعا أو كرها قالتا أتينا طائعين } فالذي خلق السماوات العظام وما فيها من الأنوار والأجرام، والأرض الكثيفة الغبراء، وما فيها من ضروريات الخلق ومنافعهم، لا بد أن يبعث الخلق المكلفين، فيجازيهم على أعمالهم، فمن أحسن فله الحسنى ومن أساء فلا يلومن إلا نفسه،","33":32,"34":"أي: إذا جاءت القيامة الكبرى، والشدة العظمى، التي يهون عندها كل شدة، فحينئذ يذهل الوالد عن ولده، والصاحب عن صاحبه [وكل محب عن حبيبه].","35":"{ يَتَذَكَّرُ الْإِنْسَانُ مَا سَعَى } في الدنيا، من خير وشر، فيتمنى زيادة مثقال ذرة في حسناته، ويغمه ويحزن لزيادة مثقال ذرة في سيئاته.ويعلم إذ ذاك أن مادة ربحه وخسرانه ما سعاه في الدنيا، وينقطع كل سبب ووصلة كانت في الدنيا سوى الأعمال.","36":"{ وَبُرِّزَتِ الْجَحِيمُ لِمَنْ يَرَى } أي: جعلت في البراز، ظاهرة لكل أحد، قد برزت لأهلها، واستعدت لأخذهم، منتظرة لأمر ربها.","37":"{ فَأَمَّا مَنْ طَغَى } أي: جاوز الحد، بأن تجرأ على المعاصي الكبار، ولم يقتصر على ما حده الله.","38":"{ وَآثَرَ الْحَيَاةَ الدُّنْيَا } على الآخرة فصار سعيه لها، ووقته مستغرقا في حظوظها وشهواتها، ونسي الآخرة وترك العمل لها.","39":"{ فَإِنَّ الْجَحِيمَ هِيَ الْمَأْوَى } له أي: المقر والمسكن لمن هذه حاله،","40":"{ وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ } أي: خاف القيام عليه ومجازاته بالعدل، فأثر هذا الخوف في قلبه فنهى نفسه عن هواها الذي يقيدها عن طاعة الله، وصار هواه تبعا لما جاء به الرسول، وجاهد الهوى والشهوة الصادين عن الخير،","41":"{ فَإِنَّ الْجَنَّةَ } [المشتملة على كل خير وسرور ونعيم] { هِيَ الْمَأْوَى } لمن هذا وصفه.","42":"أي: يسألك المتعنتون المكذبون بالبعث { عَنِ السَّاعَةِ } متى وقوعها و { أَيَّانَ مُرْسَاهَا }","43":"فأجابهم الله بقوله: { فِيمَ أَنْتَ مِنْ ذِكْرَاهَا } أي: ما الفائدة لك ولهم في ذكرها ومعرفة وقت مجيئها؟ فليس تحت ذلك نتيجة، ولهذا لما كان علم العباد للساعة ليس لهم فيه مصلحة دينية ولا دنيوية، بل المصلحة في خفائه عليهم، طوى علم ذلك عن جميع الخلق، واستأثر بعلمه","44":"{ إِلَى رَبِّكَ مُنْتَهَاهَا } أي: إليه ينتهي علمها، كما قال في الآية الأخرى: { يَسْأَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْسَاهَا قُلْ إِنَّمَا عِلْمُهَا عِنْدَ رَبِّي لَا يُجَلِّيهَا لِوَقْتِهَا إِلَّا هُوَ ثقلت في السماوات والأرض لا تأتيكم إلا بغته يسألونك كأنك حفي عنها قل إنما علمها عند الله ولكن أكثر الناس لا يعلمون } .","45":"{ إِنَّمَا أَنْتَ مُنْذِرُ مَنْ يَخْشَاهَا } أي: إنما نذارتك [نفعها] لمن يخشى مجيء الساعة، ويخاف الوقوف بين يديه، فهم الذين لا يهمهم سوى الاستعداد لها والعمل لأجلها. وأما من لا يؤمن بها، فلا يبالي به ولا بتعنته، لأنه تعنت مبني على العناد والتكذيب، وإذا وصل إلى هذه الحال، كان الإجابة عنه عبثا، ينزه الحكيم عنه [تمت] والحمد لله رب العالمين.","46":45},"80":{"1":"وسبب نزول هذه الآيات الكريمات، أنه جاء رجل من المؤمنين أعمى يسأل النبي صلى الله عليه ويتعلم منه.وجاءه رجل من الأغنياء، وكان صلى الله عليه وسلم حريصا على هداية الخلق، فمال صلى الله عليه وسلم [وأصغى] إلى الغني، وصد عن الأعمى الفقير، رجاء لهداية ذلك الغني، وطمعا في تزكيته، فعاتبه الله بهذا العتاب اللطيف، فقال: { عَبَسَ } [أي:] في وجهه { وَتَوَلَّى } في بدنه،","2":"لأجل مجيء الأعمى له،","3":"ثم ذكر الفائدة في الإقبال عليه، فقال: { وَمَا يُدْرِيكَ لَعَلَّهُ } أي: الأعمى { يَزَّكَّى } أي: يتطهر عن الأخلاق الرذيلة، ويتصف بالأخلاق الجميلة؟","4":"{ أَوْ يَذَّكَّرُ فَتَنْفَعَهُ الذِّكْرَى } أي: يتذكر ما ينفعه، فيعمل بتلك الذكرى.","5":"وهذه فائدة كبيرة، هي المقصودة من بعثة الرسل، ووعظ الوعاظ، وتذكير المذكرين، فإقبالك على من جاء بنفسه مفتقرا لذلك منك ، هو الأليق الواجب، وأما تصديك وتعرضك للغني المستغني الذي لا يسأل ولا يستفتي لعدم رغبته في الخير، مع تركك من هو أهم منه، فإنه لا ينبغي لك، فإنه ليس عليك أن لا يزكى، فلو لم يتزك، فلست بمحاسب على ما عمله من الشر.فدل هذا على القاعدة المشهورة، أنه: \\\" لا يترك أمر معلوم لأمر موهوم، ولا مصلحة متحققة لمصلحة متوهمة \\\" وأنه ينبغي الإقبال على طالب العلم، المفتقر إليه، الحريص عليه أزيد من غيره.","6":5,"7":5,"8":5,"9":5,"10":5,"11":"يقول تعالى: { كَلَّا إِنَّهَا تَذْكِرَةٌ } أي: حقا إن هذه الموعظة تذكرة من الله، يذكر بها عباده، ويبين لهم في كتابه ما يحتاجون إليه، ويبين الرشد من الغي،","12":"فإذا تبين ذلك { فَمَنْ شَاءَ ذَكَرَهُ } أي: عمل به، كقوله تعالى: { وَقُلِ الْحَقُّ مِنْ رَبِّكُمْ فَمَنْ شَاءَ فَلْيُؤْمِنْ وَمَنْ شَاءَ فَلْيَكْفُرْ }","13":"ثم ذكر محل هذه التذكرة وعظمها ورفع قدرها، فقال: { فِي صُحُفٍ مُكَرَّمَةٍ}","14":"[ مَرْفُوعَةٍ } القدر والرتبة { مُطَهَّرَةٌ } من الآفات و عن أن تنالها أيدي الشياطين أو يسترقوها","15":"{ بِأَيْدِي سَفَرَةٍ } وهم الملائكة [الذين هم] السفراء بين الله وبين عباده،","16":"{ كِرَامٍ } أي: كثيري الخير والبركة، { بَرَرَةٍ } قلوبهم وأعمالهم.وذلك كله حفظ من الله لكتابه، أن جعل السفراء فيه إلى الرسل الملائكة الكرام الأقوياء الأتقياء، ولم يجعل للشياطين عليه سبيلا، وهذا مما يوجب الإيمان به وتلقيه بالقبول، ولكن مع هذا أبى الإنسان إلا كفورا.","17":"{ قُتِلَ الْإِنْسَانُ مَا أَكْفَرَهُ } لنعمة الله وما أشد معاندته للحق بعدما تبين، وهو ما هو؟","18":"هو من أضعف الأشياء،","19":"خلقه الله من ماء مهين، ثم قدر خلقه، وسواه بشرا سويا، وأتقن قواه الظاهرة والباطنة.","20":"{ ثُمَّ السَّبِيلَ يَسَّرَهُ } أي: يسر له الأسباب الدينية والدنيوية، وهداه السبيل، [وبينه] وامتحنه بالأمر والنهي،","21":"{ ثُمَّ أَمَاتَهُ فَأَقْبَرَهُ } أي: أكرمه بالدفن، ولم يجعله كسائر الحيوانات التي تكون جيفها على وجه الأرض،","22":"{ ثُمَّ إِذَا شَاءَ أَنْشَرَهُ } أي: بعثه بعد موته للجزاء، فالله هو المنفرد بتدبير الإنسان وتصريفه بهذه التصاريف، لم يشاركه فيه مشارك،","23":"وهو -مع هذا- لا يقوم بما أمره الله، ولم يقض ما فرضه عليه، بل لا يزال مقصرا تحت الطلب.","24":"ثم أرشده تعالى إلى النظر والتفكر في طعامه، وكيف وصل إليه بعدما تكررت عليه طبقات عديدة، ويسره له فقال: { فَلْيَنْظُرِ الْإِنْسَانُ إِلَى طَعَامِهِ}","25":"[ أَنَّا صَبَبْنَا الْمَاءَ صَبًّا } أي: أنزلنا المطر على الأرض بكثرة.","26":"{ ثُمَّ شَقَقْنَا الْأَرْضَ } للنبات { شَقًّا}","27":"[ فَأَنْبَتْنَا فِيهَا } أصنافا مصنفة من أنواع الأطعمة اللذيذة، والأقوات الشهية { حبًّا } وهذا شامل لسائر الحبوب على اختلاف أصنافها،","28":"{ وَعِنَبًا وَقَضْبًا } وهو القت،","29":"{ وَزَيْتُونًا وَنَخْلًا } وخص هذه الأربعة لكثرة فوائدها ومنافعها.","30":"{ وَحَدَائِقَ غُلْبًا } أي: بساتين فيها الأشجار الكثيرة الملتفة،","31":"{ وَفَاكِهَةً وَأَبًّا } الفاكهة: ما يتفكه فيه الإنسان، من تين وعنب وخوخ ورمان، وغير ذلك.","32":"والأب: ما تأكله البهائم والأنعام، ولهذا قال: { مَتَاعًا لَكُمْ وَلِأَنْعَامِكُمْ } التي خلقها الله وسخرها لكم، فمن نظر في هذه النعم أوجب له ذلك شكر ربه، وبذل الجهد في الإنابة إليه، والإقبال على طاعته، والتصديق بأخباره.","33":"أي: إذا جاءت صيحة القيامة، التي تصخ لهولها الأسماع، وتنزعج لها الأفئدة يومئذ، مما يرى الناس من الأهوال وشدة الحاجة لسالف الأعمال.","34":"{ يَفِرُّ الْمَرْءُ } من أعز الناس إليه، وأشفقهم لديه، { مِنْ أَخِيهِ وَأُمِّهِ وَأَبِيهِ وَصَاحِبَتِهِ } أي: زوجته { وَبَنِيهِ }","35":34,"36":34,"37":"{ لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ } أي: قد شغلته نفسه، واهتم لفكاكها، ولم يكن له التفات إلى غيرها، فحينئذ ينقسم الخلق إلى فريقين: سعداء وأشقياء،","38":"فأما السعداء، فـوجوههم [يومئذ] { مُسْفِرَةٌ } أي: قد ظهر فيها السرور والبهجة، من ما عرفوا من نجاتهم، وفوزهم بالنعيم،","39":"{ ضَاحِكَةٌ مُسْتَبْشِرَةٌ}","40":"[ وَوُجُوهٌ } الأشقياء { يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ}","41":"[ تَرْهَقُهَا } أي: تغشاها { قَتَرَةٌ } فهي سوداء مظلمة مدلهمة، قد أيست من كل خير، وعرفت شقاءها وهلاكها.","42":"{ أُولَئِكَ } الذين بهذا الوصف { هُمُ الْكَفَرَةُ الْفَجَرَةُ } أي: الذين كفروا بنعمة الله وكذبوا بآيات الله، وتجرأوا على محارمه.نسأل الله العفو والعافية إنه جواد كريم [والحمد لله رب العالمين]."},"81":{"1":"أي: إذا حصلت هذه الأمور الهائلة، تميز الخلق، وعلم كل أحد ما قدمه لآخرته، وما أحضره فيها من خير وشر، وذلك إذا كان يوم القيامة تكور الشمس أي: تجمع وتلف، ويخسف القمر، ويلقيان في النار.","2":"{ وَإِذَا النُّجُومُ انْكَدَرَتْ } أي: تغيرت، وتساقطت من أفلاكها.","3":"{ وَإِذَا الْجِبَالُ سُيِّرَتْ } أي:: صارت كثيبا مهيلا، ثم صارت كالعهن المنفوش، ثم تغيرت وصارت هباء منبثا، وسيرت عن أماكنها.","4":"{ وَإِذَا الْعِشَارُ عُطِّلَتْ } أي: عطل الناس حينئذ نفائس أموالهم التي كانوا يهتمون لها ويراعونها في جميع الأوقات، فجاءهم ما يذهلهم عنها، فنبه بالعشار، وهي النوق التي تتبعها أولادها، وهي أنفس أموال العرب إذ ذاك عندهم، على ما هو في معناها من كل نفيس.","5":"{ وَإِذَا الْوُحُوشُ حُشِرَتْ } أي: جمعت ليوم القيامة، ليقتص الله من بعضها لبعض، ويرى العباد كمال عدله، حتى إنه ليقتص من القرناء للجماء ثم يقول لها: كوني ترابا.","6":"{ وَإِذَا الْبِحَارُ سُجِّرَتْ } أي: أوقدت فصارت -على عظمها- نارا تتوقد.","7":"{ وَإِذَا النُّفُوسُ زُوِّجَتْ } أي: قرن كل صاحب عمل مع نظيره، فجمع الأبرار مع الأبرار، والفجار مع الفجار، وزوج المؤمنون بالحور العين، والكافرون بالشياطين، وهذا كقوله تعالى: { وَسِيقَ الَّذِينَ كَفَرُوا إِلَى جَهَنَّمَ زُمَرًا } { وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا } { احْشُرُوا الَّذِينَ ظَلَمُوا وَأَزْوَاجَهُمْ } .","8":"{ وَإِذَا الْمَوْءُودَةُ سُئِلَتْ } وهو الذي كانت الجاهلية الجهلاء تفعله من دفن البنات وهن أحياء من غير سبب، إلا خشية الفقر.","9":"فتسأل: { بِأَيِّ ذَنْبٍ قُتِلَتْ } ومن المعلوم أنها ليس لها ذنب، ففي هذا توبيخ وتقريع لقاتليها .","10":"{ وَإِذَا الصُّحُفُ } المشتملة على ما عمله العاملون من خير وشر { نُشِرَتْ } وفرقت على أهلها، فآخذ كتابه بيمينه، وآخذ كتابه بشماله، أو من وراء ظهره.","11":"{ وَإِذَا السَّمَاءُ كُشِطَتْ } أي: أزيلت، كما قال تعالى: { يَوْمَ تَشَقَّقُ السَّمَاءُ بِالْغَمَامِ } { يَوْمَ نَطْوِي السَّمَاءَ كَطَيِّ السِّجِلِّ لِلْكُتُبِ } { وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّماوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ }","12":"{ وَإِذَا الْجَحِيمُ سُعِّرَتْ } أي: أوقد عليها فاستعرت، والتهبت التهابا لم يكن لها قبل ذلك،","13":"{ وَإِذَا الْجَنَّةُ أُزْلِفَتْ } أي: قربت للمتقين،","14":"{ عَلِمَتْ نَفْسٌ } أي: كل نفس، لإتيانها في سياق الشرط.{ مَا أَحْضَرَتْ } أي: ما حضر لديها من الأعمال [التي قدمتها] كما قال تعالى: { وَوَجَدُوا مَا عَمِلُوا حَاضِرًا } وهذه الأوصاف التي وصف الله بها يوم القيامة، من الأوصاف التي تنزعج لها القلوب، وتشتد من أجلها الكروب، وترتعد الفرائص وتعم المخاوف، وتحث أولي الألباب للاستعداد لذلك اليوم، وتزجرهم عن كل ما يوجب اللوم، ولهذا قال بعض السلف: من أراد أن ينظر ليوم القيامة كأنه رأي عين، فليتدبر سورة { إِذَا الشَّمْسُ كُوِّرَتْ }","15":"أقسم تعالى { بِالْخُنَّسِ } وهي الكواكب التي تخنس أي: تتأخر عن سير الكواكب المعتاد إلى جهة المشرق، وهي النجوم السبعة السيارة: \\\" الشمس \\\"، و \\\" القمر \\\"، و \\\" الزهرة \\\"، و \\\" المشترى \\\"، و \\\" المريخ \\\"، و \\\" زحل \\\"، و \\\" عطارد \\\"، فهذه السبعة لها سيران: سير إلى جهة المغرب مع باقي الكواكب والأفلاك ، وسير معاكس لهذا من جهة المشرق تختص به هذه السبعة دون غيرها.","16":"فأقسم الله بها في حال خنوسها أي: تأخرها، وفي حال جريانها، وفي حال كنوسها أي: استتارها بالنهار، ويحتمل أن المراد بها جميع النجوم الكواكب السيارة وغيرها.","17":"{ وَاللَّيْلِ إِذَا عَسْعَسَ } أي: أدبر وقيل: أقبل،","18":"{ وَالصُّبْحِ إِذَا تَنَفَّسَ } أي: بانت علائم الصبح، وانشق النور شيئا فشيئا حتى يستكمل وتطلع الشمس، وهذه آيات عظام، أقسم الله بها على علو سند القرآن وجلالته،","19":"وحفظه من كل شيطان رجيم فقال: { إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ } وهو: جبريل عليه السلام، نزل به من الله تعالى، كما قال تعالى: { وَإِنَّهُ لَتَنْزِيلُ رَبِّ الْعَالَمِينَ نَزَلَ بِهِ الرُّوحُ الْأَمِينُ عَلَى قَلْبِكَ لِتَكُونَ مِنَ الْمُنْذِرِينَ } ووصفه الله بالكريم لكرم أخلاقه، وكثره خصاله الحميدة، فإنه أفضل الملائكة، وأعظمهم رتبة عند ربه،","20":"{ ذِي قُوَّةٍ } على ما أمره الله به. ومن قوته أنه قلب ديار قوم لوط بهم فأهلكهم.{ عِنْدَ ذِي الْعَرْشِ } أي: جبريل مقرب عند الله، له منزلة رفيعة، وخصيصة من الله اختصه بها، { مَكِينٍ } أي: له مكانة ومنزلة فوق منازل الملائكة كلهم.","21":"{ مُطَاعٍ ثَمَّ } أي: جبريل مطاع في الملأ الأعلى، لديه من الملائكة المقربين جنود، نافذ فيهم أمره، مطاع رأيه، { أَمِينٍ } أي: ذو أمانة وقيام بما أمر به، لا يزيد ولا ينقص، ولا يتعدى ما حد له، وهذا [كله] يدل على شرف القرآن عند الله تعالى، فإنه بعث به هذا الملك الكريم، الموصوف بتلك الصفات الكاملة. والعادة أن الملوك لا ترسل الكريم عليها إلا في أهم المهمات، وأشرف الرسائل.","22":"ولما ذكر فضل الرسول الملكي الذي جاء بالقرآن، ذكر فضل الرسول البشري الذي نزل عليه القرآن، ودعا إليه الناس فقال: { وَمَا صَاحِبُكُمْ } وهو محمد صلى الله عليه وسلم { بِمَجْنُونٍ } كما يقوله أعداؤه المكذبون برسالته، المتقولون عليه من الأقوال، التي يريدون أن يطفئوا بها ما جاء به ما شاءوا وقدروا عليه، بل هو أكمل الناس عقلا، وأجزلهم رأيا، وأصدقهم لهجة.","23":"{ وَلَقَدْ رَآهُ بِالْأُفُقِ الْمُبِينِ } أي: رأى محمد صلى الله عليه وسلم جبريل عليه السلام بالأفق البين، الذي هو أعلى ما يلوح للبصر.","24":"{ وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ } أي: وما هو على ما أوحاه الله إليه بمتهم يزيد فيه أو ينقص أو يكتم بعضه، بل هو صلى الله عليه وسلم أمين أهل السماء وأهل الأرض، الذي بلغ رسالات ربه البلاغ المبين، فلم يشح بشيء منه، عن غني ولا فقير، ولا رئيس ولا مرءوس، ولا ذكر ولا أنثى، ولا حضري ولا بدوي، ولذلك بعثه الله في أمة أمية، جاهلة جهلاء، فلم يمت صلى الله عليه وسلم حتى كانوا علماء ربانيين، وأحبارا متفرسين، إليهم الغاية في العلوم، وإليهم المنتهى في استخراج الدقائق والفهوم، وهم الأساتذة، وغيرهم قصاراه أن يكون من تلاميذهم.","25":"{ وَمَا هُوَ بِقَوْلِ شَيْطَانٍ رَجِيمٍ } لما ذكر جلالة كتابه وفضله بذكر الرسولين الكريمين، اللذين وصل إلى الناس على أيديهما، وأثنى الله عليهما بما أثنى، دفع عنه كل آفة ونقص مما يقدح في صدقه، فقال: { وَمَا هُوَ بِقَوْلِ شَيْطَانٍ رَجِيمٍ } أي: في غاية البعد عن الله وعن قربه،","26":"{ فَأَيْنَ تَذْهَبُونَ } أي: كيف يخطر هذا ببالكم، وأين عزبت عنكم أذهانكم؟ حتى جعلتم الحق الذي هو في أعلى درجات الصدق بمنزلة الكذب، الذي هو أنزل ما يكون [وأرذل] وأسفل الباطل؟ هل هذا إلا من انقلاب الحقائق.","27":"{ إِنْ هُوَ إِلَّا ذِكْرٌ لِلْعَالَمِينَ } يتذكرون به ربهم، وما له من صفات الكمال، وما ينزه عنه من النقائص والرذائل [والأمثال]، ويتذكرون به الأوامر والنواهي وحكمها، ويتذكرون به الأحكام القدرية والشرعية والجزائية، وبالجملة، يتذكرون به مصالح الدارين، وينالون بالعمل به السعادتين.","28":"{ لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ } بعدما تبين الرشد من الغي، والهدى من الضلال.","29":"{ وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ } أي: فمشيئته نافذة، لا يمكن أن تعارض أو تمانع. وفي هذه الآية وأمثالها رد على فرقتي القدرية النفاة، والقدرية المجبرة كما تقدم مثلها [والله أعلم والحمد لله]."},"82":{"1":"أي: إذا انشقت السماء وانفطرت،","2":"وانتثرت نجومها، وزال جمالها،","3":"وفجرت البحار فصارت بحرا واحدا،","4":"وبعثرت القبور بأن أخرجت ما فيها من الأموات،","5":"وحشروا للموقف بين يدي الله للجزاء على الأعمال. فحينئذ ينكشف الغطاء، ويزول ما كان خفيا، وتعلم كل نفس ما معها من الأرباح والخسران، هنالك يعض الظالم على يديه إذا رأى أعماله باطلة، وميزانه قد خف، والمظالم قد تداعت إليه، والسيئات قد حضرت لديه، وأيقن بالشقاء الأبدي والعذاب السرمدي .و [هنالك] يفوز المتقون المقدمون لصالح الأعمال بالفوز العظيم، والنعيم المقيم والسلامة من عذاب الجحيم.","6":"يقول تعالى معاتبا للإنسان المقصر في حق ربه، المتجرئ على مساخطه : { يَا أَيُّهَا الْإِنْسَانُ مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ } أتهاونا منك في حقوقه؟ أم احتقارا منك لعذابه؟ أم عدم إيمان منك بجزائه؟","7":"أليس هو { الَّذِي خَلَقَكَ فَسَوَّاكَ } في أحسن تقويم؟ { فَعَدَلَكَ } وركبك تركيبا قويما معتدلا، في أحسن الأشكال، وأجمل الهيئات، فهل يليق بك أن تكفر نعمة المنعم، أو تجحد إحسان المحسن؟","8":"إن هذا إلا من جهلك وظلمك وعنادك وغشمك، فاحمد الله أن لم يجعل صورتك صورة كلب أو حمار، أو نحوهما من الحيوانات؛ فلهذا قال تعالى: { فِي أَيِّ صُورَةٍ مَا شَاءَ رَكَّبَكَ }","9":"{ كَلَّا بَلْ تُكَذِّبُونَ بِالدِّينِ } أي: مع هذا الوعظ والتذكير، لا تزالون مستمرين على التكذيب بالجزاء.","10":"وأنتم لا بد أن تحاسبوا على ما عملتم، وقد أقام الله عليكم ملائكة كراما يكتبون أقوالكم وأفعالكم ويعلمون أفعالكم، ودخل في هذا أفعال القلوب، وأفعال الجوارح، فاللائق بكم أن تكرموهم وتجلوهم وتحترموهم.","11":10,"12":"يكتبون أقوالكم وأفعالكم ويعلمونها، ودخل في هذا أفعال القلوب، وأفعال الجوارح، فاللائق بكم أن تكرموهم وتجلوهم وتحترموهم.","13":"المراد بالأبرار، القائمون بحقوق الله وحقوق عباده، الملازمون للبر، في أعمال القلوب وأعمال الجوارح، فهؤلاء جزاؤهم النعيم في القلب والروح والبدن، في دار الدنيا [وفي دار] البرزخ و [في] دار القرار.","14":"{ وَإِنَّ الْفُجَّارَ } الذين قصروا في حقوق الله وحقوق عباده، الذين فجرت قلوبهم ففجرت أعمالهم { لَفِي جَحِيمٍ } أي: عذاب أليم، في دار الدنيا و [دار] البرزخ وفي دار القرار.","15":"{ يَصْلَوْنَهَا } ويعذبون [بها] أشد العذاب { يَوْمِ الدِّينِ } أي: يوم الجزاء على الأعمال.","16":"{ وَمَا هُمْ عَنْهَا بِغَائِبِينَ } أي: بل هم ملازمون لها، لا يخرجون منها.","17":"{ وَمَا أَدْرَاكَ مَا يَوْمُ الدِّينِ ثُمَّ مَا أَدْرَاكَ مَا يَوْمُ الدِّينِ } ففي هذا تهويل لذلك اليوم الشديد الذي يحير الأذهان.","18":17,"19":"{ يَوْمَ لَا تَمْلِكُ نَفْسٌ لِنَفْسٍ شَيْئًا } ولو كانت لها قريبة أو حبيبة مصافية، فكل مشتغل بنفسه لا يطلب الفكاك لغيرها. { وَالْأَمْرُ يَوْمَئِذٍ لِلَّهِ } فهو الذي يفصل بين العباد، ويأخذ للمظلوم حقه من ظالمه والله أعلم."},"83":{"1":"{ وَيْلٌ } كلمة عذاب، ووعيد { لِلْمُطَفِّفِينَ }","2":"وفسر الله المطففين بقوله { الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ } أي: أخذوا منهم وفاء عما ثبت لهم قبلهم { يَسْتَوْفُونَ } يستوفونه كاملا من غير نقص.","3":"{ وَإِذَا كَالُوهُمْ أَوْ وَزَنُوهُمْ } أي: إذا أعطوا الناس حقهم، الذي للناس عليهم بكيل أو وزن، { يُخْسِرُونَ } أي: ينقصونهم ذلك، إما بمكيال وميزان ناقصين، أو بعدم ملء المكيال والميزان، أو نحو ذلك. فهذا سرقة [لأموال] الناس ، وعدم إنصاف [لهم] منهم.وإذا كان هذا الوعيد على الذين يبخسون الناس بالمكيال والميزان، فالذي يأخذ أموالهم قهرًا أو سرقة، أولى بهذا الوعيد من المطففين.ودلت الآية الكريمة، على أن الإنسان كما يأخذ من الناس الذي له، يجب عليه أن يعطيهم كل ما لهم من الأموال والمعاملات، بل يدخل في [عموم هذا] الحجج والمقالات، فإنه كما أن المتناظرين قد جرت العادة أن كل واحد [منهما] يحرص على ماله من الحجج، فيجب عليه أيضًا أن يبين ما لخصمه من الحجج [التي لا يعلمها]، وأن ينظر في أدلة خصمه كما ينظر في أدلته هو، وفي هذا الموضع يعرف إنصاف الإنسان من تعصبه واعتسافه، وتواضعه من كبره، وعقله من سفهه، نسأل الله التوفيق لكل خير.","4":"ثم توعد تعالى المطففين، وتعجب من حالهم وإقامتهم على ما هم عليه، فقال: { أَلَا يَظُنُّ أُولَئِكَ أَنَّهُمْ مَبْعُوثُونَ لِيَوْمٍ عَظِيمٍ يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ } فالذي جرأهم على التطفيف عدم إيمانهم باليوم الآخر، وإلا فلو آمنوا به، وعرفوا أنهم يقومون بين يدى الله، يحاسبهم على القليل والكثير، لأقلعوا عن ذلك وتابوا منه.","5":4,"6":4,"7":"يقول تعالى: { كَلَّا إِنَّ كِتَابَ الْفُجَّارِ } [وهذا شامل لكل فاجر] من أنواع الكفرة والمنافقين، والفاسقين { لَفِي سِجِّينٍ }","8":"{ وَمَا أَدْرَاكَ مَا سِجِّينٌ كِتَابٌ مَرْقُومٌ } أي: كتاب مذكور فيه أعمالهم الخبيثة، والسجين: المحل الضيق الضنك، و { سجين } ضد { عليين } الذي هو محل كتاب الأبرار، كما سيأتي.وقد قيل: إن { سجين } هو أسفل الأرض السابعة، مأوى الفجار ومستقرهم في معادهم.","9":8,"10":"{ وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ }","11":"ثم بين المكذبين بأنهم { الَّذِينَ يُكَذِّبُونَ بِيَوْمِ الدِّينِ } أي: يوم الجزاء، يوم يدين الله فيه الناس بأعمالهم.","12":"{ وَمَا يُكَذِّبُ بِهِ إِلَّا كُلُّ مُعْتَدٍ } على محارم الله، متعد من الحلال إلى الحرام.{ أَثِيمٍ } أي كثير الإثم، فهذا الذي يحمله عدوانه على التكذيب، ويحمله [عدوانه على التكذيب ويوجب له] كبره رد الحق،","13":"ولهذا { إِذَا تُتْلَى عَلَيْهِ آيَاتُنَا } الدالة على الحق، و[على] صدق ما جاءت به رسله، كذبها وعاندها، و { قَالَ } هذه { أَسَاطِيرُ الْأَوَّلِينَ } أي: من ترهات المتقدمين، وأخبار الأمم الغابرين، ليس من عند الله تكبرا وعنادا.","14":"وأما من أنصف، وكان مقصوده الحق المبين، فإنه لا يكذب بيوم الدين، لأن الله قد أقام عليه من الأدلة القاطعة، والبراهين الساطعة، ما يجعله حق اليقين، وصار لقلوبهم مثل الشمس للأبصار ، بخلاف من ران على قلبه كسبه، وغطته معاصيه،","15":"فإنه محجوب عن الحق، ولهذا جوزي على ذلك، بأن حجب عن الله، كما حجب قلبه في الدنيا عن آيات الله،","16":"{ ثُمَّ إِنَّهُمْ } مع هذه العقوبة البليغة { لَصَالُوا الْجَحِيمِ }","17":"ثم يقال لهم توبيخا وتقريعًا: هَذَا الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ } فذكر لهم ثلاثة أنواع من العذاب: عذاب الجحيم، وعذاب التوبيخ، واللوم.وعذاب الحجاب من رب العالمين، المتضمن لسخطه وغضبه عليهم، وهو أعظم عليهم من عذاب النار، ودل مفهوم الآية، على أن المؤمنين يرون ربهم يوم القيامة وفي الجنة، ويتلذذون بالنظر إليه أعظم من سائر اللذات، ويبتهجون بخطابه، ويفرحون بقربه، كما ذكر الله ذلك في عدة آيات من القرآن، وتواتر فيه النقل عن رسول الله.وفي هذه الآيات، التحذير من الذنوب، فإنها ترين على القلب وتغطيه شيئا فشيئا، حتى ينطمس نوره، وتموت بصيرته، فتنقلب عليه الحقائق، فيرى الباطل حقًا، والحق باطلًا، وهذا من بعض عقوبات الذنوب.","18":"لما ذكر أن كتاب الفجار في أسفل الأمكنة وأضيقها، ذكر أن كتاب الأبرار في أعلاها وأوسعها، وأفسحها","19":18,"20":18,"21":"وأن كتابهم المرقوم { يَشْهَدُهُ الْمُقَرَّبُونَ } من الملائكة الكرام، وأرواح الأنبياء، والصديقين والشهداء، وينوه الله بذكرهم في الملأ الأعلى، و { عليون } اسم لأعلى الجنة،","22":"فلما ذكر كتابهم، ذكر أنهم في نعيم، وهو اسم جامع لنعيم القلب والروح والبدن،","23":"{ عَلَى الْأَرَائِكِ } أي: [على] السرر المزينة بالفرش الحسان.{ يُنْظَرُونَ } إلى ما أعد الله لهم من النعيم, وينظرون إلى وجه ربهم الكريم،","24":"{ تَعْرِفُ } أيها الناظر إليهم { فِي وُجُوهِهِمْ نَضْرَةَ النَّعِيمِ } أي: بهاء النعيم ونضارته ورونقه، فإن توالي اللذة والسرور يكسب الوجه نورًا وحسنًا وبهجة.","25":"{ يُسْقَوْنَ مِنْ رَحِيقٍ } وهو من أطيب ما يكون من الأشربة وألذها، { مَخْتُومٍ }","26":"ذلك الشراب { خِتَامُهُ مِسْكٌ } يحتمل أن المراد مختوم عن أن يداخله شيء ينقص لذته، أو يفسد طعمه، وذلك الختام، الذي ختم به, مسك.ويحتمل أن المراد أنه [الذي] يكون في آخر الإناء، الذي يشربون منه الرحيق حثالة، وهي المسك الأذفر، فهذا الكدر منه، الذي جرت العادة في الدنيا أنه يراق, يكون في الجنة بهذه المثابة، { وَفِي ذَلِكَ } النعيم المقيم، الذي لا يعلم حسنه ومقداره إلا الله، { فَلْيَتَنَافَسِ الْمُتَنَافِسُونَ } أي: يتسابقوا في المبادرة إليه بالأعمال الموصلة إليه، فهذا أولى ما بذلت فيه نفائس الأنفاس، وأحرى ما تزاحمت للوصول إليه فحول الرجال.","27":"ومزاج هذا الشراب من تسنيم،","28":"وهي عين { يَشْرَبُ بِهَا الْمُقَرَّبُونَ } صرفا، وهي أعلى أشربة الجنة على الإطلاق، فلذلك كانت خالصة للمقربين، الذين هم أعلى الخلق منزلة، وممزوجة لأصحاب اليمين أي: مخلوطة بالرحيق وغيره من الأشربة اللذيذة.","29":"لما ذكر تعالى جزاء المجرمين وجزاء المؤمنين و [ذكر] ما بينهما من التفاوت العظيم، أخبر أن المجرمين كانوا في الدنيا يسخرون بالمؤمنين، ويستهزئون بهم، ويضحكون منهم،","30":"ويتغامزون بهم عند مرورهم عليهم، احتقارا لهم وازدراء، ومع هذا تراهم مطمئنين، لا يخطر الخوف على بالهم،","31":"{ وَإِذَا انْقَلَبُوا إِلَى أَهْلِهِمُ } صباحًا أو مساء { انْقَلَبُوا فَكِهِينَ } أي: مسرورين مغتبطين ،","32":"وهذا من أعظم ما يكون من الاغترار، أنهم جمعوا بين غاية الإساءة والأمن في الدنيا، حتى كأنهم قد جاءهم كتاب من الله وعهد، أنهم من أهل السعادة، وقد حكموا لأنفسهم أنهم أهل الهدى، وأن المؤمنين ضالون، افتراء على الله، وتجرأوا على القول عليه بلا علم.","33":"{ وَمَا أُرْسِلُوا عَلَيْهِمْ حَافِظِينَ } أي: وما أرسلوا وكلاء على المؤمنين ملزمين بحفظ أعمالهم، حتى يحرصوا على رميهم بالضلال، وما هذا منهم إلا تعنت وعناد وتلاعب، ليس له مستند ولا برهان،","34":"ولهذا كان جزاؤهم في الآخرة من جنس عملهم، قال تعالى: { فَالْيَوْمَ } أي: يوم القيامة، { الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ } حين يرونهم في غمرات العذاب يتقلبون، وقد ذهب عنهم ما كانوا يفترون، والمؤمنون في غاية الراحة والطمأنينة","35":"{ عَلَى الْأَرَائِكِ } وهي السرر المزينة، { يُنْظَرُونَ } إلى ما أعد الله لهم من النعيم، وينظرون إلى وجه ربهم الكريم.","36":"{ هَلْ ثُوِّبَ الْكُفَّارُ مَا كَانُوا يَفْعَلُونَ } أي: هل جوزوا من جنس عملهم؟فكما ضحكوا في الدنيا من المؤمنين ورموهم بالضلال، ضحك المؤمنون منهم في الآخرة، ورأوهم في العذاب والنكال، الذي هو عقوبة الغي والضلال.نعم، ثوبوا ما كانوا يفعلون، عدلًا من الله وحكمة، والله عليم حكيم."},"84":{"1":"يقول تعالى مبينًا لما يكون في يوم القيامة من تغير الأجرام العظام: { إِذَا السَّمَاءُ انْشَقَّتْ } أي: انفطرت وتمايز بعضها من بعض، وانتثرت نجومها، وخسف بشمسها وقمرها.","2":"{ وَأَذِنَتْ لِرَبِّهَا } أي: استمعت لأمره، وألقت سمعها، وأصاخت لخطابه، وحق لها ذلك، فإنها مسخرة مدبرة تحت مسخر ملك عظيم، لا يعصى أمره، ولا يخالف حكمه.","3":"{ وَإِذَا الْأَرْضُ مُدَّتْ } أي: رجفت وارتجت، ونسفت عليها جبالها، ودك ما عليها من بناء ومعلم، فسويت، ومدها الله تعالى مد الأديم، حتى صارت واسعة جدًا، تسع أهل الموقف على كثرتهم، فتصير قاعًا صفصفًا لا ترى فيها عوجًا ولا أمتا.","4":"{ وَأَلْقَتْ مَا فِيهَا } من الأموات والكنوز. { وَتَخَلَّتْ } منهم، فإنه ينفخ في الصور، فتخرج الأموات من الأجداث إلى وجه الأرض، وتخرج الأرض كنوزها، حتى تكون كالأسطوان العظيم، يشاهده الخلق، ويتحسرون على ما هم فيه يتنافسون.","5":"{ وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ}","6":"[يَا أَيُّهَاالْإِنْسَانُ إِنَّكَ كَادِحٌ إِلَى رَبِّكَ كَدْحًا فَمُلَاقِيهِ } أي: إنك ساع إلى الله، وعامل بأوامره ونواهيه، ومتقرب إليه إما بالخير وإما بالشر، ثم تلاقي الله يوم القيامة، فلا تعدم منه جزاء بالفضل إن كنت سعيدًا، أو بالعدل إن كنت شقيًا .","7":"ولهذا ذكر تفضيل الجزاء، فقال: { فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ } وهم أهل السعادة.","8":"{ فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا } وهو العرض اليسير على الله، فيقرره الله بذنوبه، حتى إذا ظن العبد أنه قد هلك، قال الله [تعالى] له: \\\" إني قد سترتها عليك في الدنيا، فأنا أسترها لك اليوم \\\".","9":"{ وَيَنْقَلِبُ إِلَى أَهْلِهِ } في الجنة { مَسْرُورًا } لأنه نجا من العذاب وفاز بالثواب.","10":"{ وَأَمَّا مَنْ أُوتِيَ كِتَابَهُ وَرَاءَ ظَهْرِهِ } أي: بشماله من خلفه.","11":"{ فَسَوْفَ يَدْعُو ثُبُورًا } من الخزي والفضيحة، وما يجد في كتابه من الأعمال التي قدمها ولم يتب منها.","12":"{ وَيَصْلَى سَعِيرًا } أي: تحيط به السعير من كل جانب، ويقلب على عذابها، وذلك لأنه في الدنيا","13":"{ كَانَ فِي أَهْلِهِ مَسْرُورًا } لا يخطر البعث على باله، وقد أساء.","14":"ولم يظن أنه راجع إلى ربه وموقوف بين يديه.","15":"{ بَلَى إِنَّ رَبَّهُ كَانَ بِهِ بَصِيرًا } فلا يحسن أن يتركه سدى، لا يؤمر ولا ينهى، ولا يثاب ولا يعاقب.","16":"أقسم في هذا الموضع بآيات الليل، فأقسم بالشفق الذي هو بقية نور الشمس، الذي هو مفتتح الليل.","17":"{ وَاللَّيْلِ وَمَا وَسَقَ } أي: احتوى عليه من حيوانات وغيرها.","18":"{ وَالْقَمَرِ إِذَا اتَّسَقَ } أي: امتلأ نورًا بإبداره، وذلك أحسن ما يكون وأكثر منافع.","19":"والمقسم عليه قوله: { لَتَرْكَبُنَّ } [أي:] أيها الناس { طَبَقًا عَنْ طَبَقٍ } أي: أطوارا متعددة وأحوالا متباينة، من النطفة إلى العلقة، إلى المضغة، إلى نفخ الروح، ثم يكون وليدًا وطفلًا، ثم مميزًا، ثم يجري عليه قلم التكليف، والأمر والنهي، ثم يموت بعد ذلك، ثم يبعث ويجازى بأعماله، فهذه الطبقات المختلفة الجارية على العبد، دالة على أن الله وحده هو المعبود، الموحد، المدبر لعباده بحكمته ورحمته، وأن العبد فقير عاجز، تحت تدبير العزيز الرحيم.","20":"ومع هذا، فكثير من الناس لا يؤمنون.","21":"{ وَإِذَا قُرِئَ عَلَيْهِمُ الْقُرْآنُ لَا يَسْجُدُونَ } أي: لا يخضعون للقرآن، ولا ينقادون لأوامره ونواهيه،","22":"{ بَلِ الَّذِينَ كَفَرُوا يُكَذِّبُونَ } أي: يعاندون الحق بعدما تبين، فلا يستغرب عدم إيمانهم وعدم انقيادهم للقرآن، فإن المكذب بالحق عنادًا، لا حيلة فيه.","23":"{ وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ } أي: بما يعملونه وينوونه سرًا، فالله يعلم سرهم وجهرهم، وسيجازيهم بأعمالهم.","24":"{ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ } وسميت البشارة بشارة، لأنها تؤثر في البشرة سرورًا أو غمًا. فهذه حال أكثر الناس، التكذيب بالقرآن، وعدم الإيمان [به].","25":"ومن الناس فريق هداهم الله، فآمنوا بالله، وقبلوا ما جاءتهم به الرسل، فآمنوا وعملوا الصالحات. فهؤلاء لهم أجر غير ممنون أي: غير مقطوع بل هو أجر دائم مما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر. تم تفسير السورة ولله الحمد."},"85":{"1":"{ وَالسَّمَاءِ ذَاتِ الْبُرُوجِ } أي: [ذات] المنازل المشتملة على منازل الشمس والقمر، والكواكب المنتظمة في سيرها، على أكمل ترتيب ونظام دال على كمال قدرة الله تعالى ورحمته، وسعة علمه وحكمته.","2":"{ وَالْيَوْمِ الْمَوْعُودِ } وهو يوم القيامة، الذي وعد الله الخلق أن يجمعهم فيه، ويضم فيه أولهم وآخرهم، وقاصيهم ودانيهم، الذي لا يمكن أن يتغير، ولا يخلف الله الميعاد.","3":"{ وَشَاهِدٍ وَمَشْهُودٍ } وشمل هذا كل من اتصف بهذا الوصف أي: مبصر ومبصر، وحاضر ومحضور، وراء ومرئي.","4":"والمقسم عليه، ما تضمنه هذا القسم من آيات الله الباهرة، وحكمه الظاهرة، ورحمته الواسعة.وقيل: إن المقسم عليه قوله { قُتِلَ أَصْحَابُ الْأُخْدُودِ } وهذا دعاء عليهم بالهلاك.و { الأخدود } الحفر التي تحفر في الأرض.وكان أصحاب الأخدود هؤلاء قومًا كافرين، ولديهم قوم مؤمنون، فراودوهم للدخول في دينهم، فامتنع المؤمنون من ذلك، فشق الكافرون أخدودًا [في الأرض]، وقذفوا فيها النار، وقعدوا حولها، وفتنوا المؤمنين، وعرضوهم عليها، فمن استجاب لهم أطلقوه، ومن استمر على الإيمان قذفوه في النار، وهذا في غاية المحاربة لله ولحزبه المؤمنين، ولهذا لعنهم الله وأهلكهم وتوعدهم فقال: { قُتِلَ أَصْحَابُ الْأُخْدُودِ }","5":"ثم فسر الأخدود بقوله: { النَّارِ ذَاتِ الْوَقُودِ إِذْ هُمْ عَلَيْهَا قُعُودٌ وَهُمْ عَلَى مَا يَفْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٌ } وهذا من أعظم ما يكون من التجبر وقساوة القلب، لأنهم جمعوا بين الكفر بآيات الله ومعاندتها، ومحاربة أهلها وتعذيبهم بهذا العذاب، الذي تنفطر منه القلوب، وحضورهم إياهم عند إلقائهم فيها، والحال أنهم ما نقموا من المؤمنين إلا خصلة يمدحون عليها، وبها سعادتهم، وهي أنهم كانوا يؤمنون بالله العزيز الحميد أي: الذي له العزة التي قهر بها كل شيء، وهو حميد في أقواله وأوصافه وأفعاله.","6":5,"7":5,"8":5,"9":"{ الَّذِي لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ } خلقًا وعبيدًا، يتصرف فيهم تصرف المالك بملكه ، { وَاللَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ } علمًا وسمعًا وبصرًا، أفلا خاف هؤلاء المتمردون على الله، أن يبطش بهم العزيز المقتدر، أو ما علموا أنهم جميعهم مماليك لله ، ليس لأحد على أحد سلطة، من دون إذن المالك؟ أو خفي عليهم أن الله محيط بأعمالهم، مجاز لهم على فعالهم ؟ كلا إن الكافر في غرور، والظالم في جهل وعمى عن سواء السبيل.","10":"ثم وعدهم، وأوعدهم، وعرض عليهم التوبة، فقال: { إِنَّ الَّذِينَ فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ ثُمَّ لَمْ يَتُوبُوا فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ الْحَرِيقِ } أي: العذاب الشديد المحرق.قال الحسن رحمه الله: انظروا إلى هذا الكرم والجود، هم قتلوا أولياءه وأهل طاعته، وهو يدعوهم إلى التوبة.","11":"ولما ذكر عقوبة الظالمين، ذكر ثواب المؤمنين، فقال: { إِنَّ الَّذِينَ آمَنُوا } بقلوبهم { وَعَمِلُوا الصَّالِحَاتِ } بجوارحهم { لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ ذَلِكَ الْفَوْزُ الْكَبِيرُ } الذي حصل به الفوز برضا الله ودار كرامته.","12":"{ إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ } أي: إن عقوبته لأهل الجرائم والذنوب العظام [لقوية] شديدة، وهو بالمرصاد للظالمين كما قال الله تعالى: { وَكَذَلِكَ أَخْذُ رَبِّكَ إِذَا أَخَذَ الْقُرَى وَهِيَ ظَالِمَةٌ إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ }","13":"{ إِنَّهُ هُوَ يُبْدِئُ وَيُعِيدُ } أي: هو المنفرد بإبداء الخلق وإعادته، فلا مشارك له في ذلك .","14":"{ وَهُوَ الْغَفُورُ } الذي يغفر الذنوب جميعها لمن تاب، ويعفو عن السيئات لمن استغفره وأناب.{ الْوَدُودُ } الذي يحبه أحبابه محبة لا يشبهها شيء فكما أنه لا يشابهه شيء في صفات الجلال والجمال، والمعاني والأفعال، فمحبته في قلوب خواص خلقه، التابعة لذلك، لا يشبهها شيء من أنواع المحاب، ولهذا كانت محبته أصل العبودية، وهي المحبة التي تتقدم جميع المحاب وتغلبها، وإن لم يكن غيرها تبعًا لها، كانت عذابًا على أهلها، وهو تعالى الودود، الواد لأحبابه، كما قال تعالى: { يُحِبُّهُمْ وَيُحِبُّونَهُ } والمودة هي المحبة الصافية، وفي هذا سر لطيف، حيث قرن { الودود } بالغفور، ليدل ذلك على أن أهل الذنوب إذا تابوا إلى الله وأنابوا، غفر لهم ذنوبهم وأحبهم، فلا يقال: بل تغفر ذنوبهم، ولا يرجع إليهم الود، كما قاله بعض الغالطين.بل الله أفرح بتوبة عبده حين يتوب، من رجل له راحلة، عليها طعامه وشرابه وما يصلحه، فأضلها في أرض فلاة مهلكة، فأيس منها، فاضطجع في ظل شجرة ينتظر الموت، فبينما هو على تلك الحال، إذا راحلته على رأسه، فأخذ بخطامها، فالله أعظم فرحًا بتوبة العبد من هذا براحلته، وهذا أعظم فرح يقدر.فلله الحمد والثناء، وصفو الوداد، ما أعظم بره، وأكثر خيره، وأغزر إحسانه، وأوسع امتنانه\\\"","15":"{ ذُو الْعَرْشِ الْمَجِيدُ } أي: صاحب العرش العظيم، الذي من عظمته، أنه وسع السماوات والأرض والكرسي، فهي بالنسبة إلى العرش كحلقة ملقاة في فلاة، بالنسبة لسائر الأرض، وخص الله العرش بالذكر، لعظمته، ولأنه أخص المخلوقات بالقرب منه تعالى، وهذا على قراءة الجر، يكون { المجيد } نعتا للعرش، وأما على قراءة الرفع، فإن المجيد نعت لله ، والمجد سعة الأوصاف وعظمتها.","16":"{ فَعَّالٌ لِمَا يُرِيدُ } أي: مهما أراد شيئًا فعله، إذا أراد شيئًا قال له كن فيكون، وليس أحد فعالًا لما يريد إلا الله.فإن المخلوقات، ولو أرادت شيئًا، فإنه لا بد لإرادتها من معاون وممانع، والله لا معاون لإرادته، ولا ممانع له مما أراد.","17":"ثم ذكر من أفعاله الدالة على صدق ما جاءت به رسله، فقال: { هَلْ أَتَاكَ حَدِيثُ الْجُنُودِ فِرْعَوْنَ وَثَمُود } وكيف كذبوا المرسلين، فجعلهم الله من المهلكين.","18":17,"19":"{ بَلِ الَّذِينَ كَفَرُوا فِي تَكْذِيبٍ } أي: لا يزالون مستمرين على التكذيب والعناد، لا تنفع فيهم الآيات، ولا تجدي لديهم العظات.","20":"{ وَاللَّهُ مِنْ وَرَائِهِمْ مُحِيطٌ } أي: قد أحاط بهم علمًا وقدرة، كقوله: { إِنَّ رَبَّكَ لَبِالْمِرْصَادِ } ففيه الوعيد الشديد للكافرين، من عقوبة من هم في قبضته، وتحت تدبيره.","21":"{ بَلْ هُوَ قُرْآنٌ مَجِيدٌ } أي: وسيع المعاني عظيمها، كثير الخير والعلم.","22":"{ فِي لَوْحٍ مَحْفُوظٍ } من التغيير والزيادة والنقص، ومحفوظ من الشياطين، وهو: اللوح المحفوظ الذي قد أثبت الله فيه كل شيء.وهذا يدل على جلالة القرآن وجزالته، ورفعة قدره عند الله تعالى، والله أعلم.تم تفسير السورة."},"86":{"1":"يقول [الله] تعالى: { وَالسَّمَاءِ وَالطَّارِقِ }","2":1,"3":"ثم فسر الطارق بقوله: { النَّجْمُ الثَّاقِبُ } أي: المضيء، الذي يثقب نوره، فيخرق السماوات [فينفذ حتى يرى في الأرض]، والصحيح أنه اسم جنس يشمل سائر النجوم الثواقب.وقد قيل: إنه \\\" زحل \\\" الذي يخرق السماوات السبع وينفذ فيها فيرى منها. وسمي طارقًا، لأنه يطرق ليلًا.","4":"والمقسم عليه قوله: { إِنْ كُلُّ نَفْسٍ لَمَّا عَلَيْهَا حَافِظٌ } يحفظ عليها أعمالها الصالحة والسيئة، وستجازى بعملها المحفوظ عليها.","5":"{ فَلْيَنْظُرِ الْإِنْسَانُ مِمَّ خُلِقَ } أي: فليتدبر خلقته ومبدأه.","6":"فإنه مخلوق { مِنْ مَاءٍ دَافِقٍ } وهو: المني","7":"المني الذي { يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ } يحتمل أنه من بين صلب الرجل وترائب المرأة، وهي ثدياها.ويحتمل أن المراد المني الدافق، وهو مني الرجل، وأن محله الذي يخرج منه ما بين صلبه وترائبه، ولعل هذا أولى، فإنه إنما وصف الله به الماء الدافق، والذي يحس [به] ويشاهد دفقه، هو مني الرجل، وكذلك لفظ الترائب فإنها تستعمل في الرجل، فإن الترائب للرجل، بمنزلة الثديين للأنثى، فلو أريدت الأنثى لقال: \\\" من بين الصلب والثديين \\\" ونحو ذلك، والله أعلم.","8":"فالذي أوجد الإنسان من ماء دافق، يخرج من هذا الموضع الصعب، قادر على رجعه في الآخرة، وإعادته للبعث، والنشور [والجزاء] ، وقد قيل: إن معناه، أن الله على رجع الماء المدفوق في الصلب لقادر، وهذا - وإن كان المعنى صحيحًا - فليس هو المراد من الآية.","9":"{ يَوْمَ تُبْلَى السَّرَائِرُ } أي: تختبر سرائر الصدور، ويظهر ما كان في القلوب من خير وشر على صفحات الوجوه قال تعالى: { يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ } ففي الدنيا، تنكتم كثير من الأمور، ولا تظهر عيانًا للناس، وأما في القيامة، فيظهر بر الأبرار، وفجور الفجار، وتصير الأمور علانية.","10":"{ فَمَا لَهُ مِنْ قُوَّةٍ } يدفع بها عن نفسه { وَلَا نَاصِرٍ } خارجي ينتصر به، فهذا القسم على حالة العاملين وقت عملهم وعند جزائهم.","11":"ثم أقسم قسمًا ثانيًا على صحة القرآن، فقال: { وَالسَّمَاءِ ذَاتِ الرَّجْعِ وَالْأَرْضِ ذَاتِ الصَّدْعِ } أي: ترجع السماء بالمطر كل عام، وتنصدع الأرض للنبات، فيعيش بذلك الآدميون والبهائم، وترجع السماء أيضًا بالأقدار والشئون الإلهية كل وقت، وتنصدع الأرض عن الأموات .","12":11,"13":"{ إِنَّه } أي: القرآن { لَقَوْلٌ فَصْلٌ } أي: حق وصدق بين واضح.","14":"{ وَمَا هُوَ بِالْهَزْلِ } أي: جد ليس بالهزل، وهو القول الذي يفصل بين الطوائف والمقالات، وتنفصل به الخصومات.{ إِنَّهُمْ } أي: المكذبين للرسول صلى الله عليه وسلم، وللقرآن","15":"{ يَكِيدُونَ كَيْدًا } ليدفعوا بكيدهم الحق، ويؤيدوا الباطل.","16":"{ وَأَكِيدُ كَيْدًا } لإظهار الحق، ولو كره الكافرون، ولدفع ما جاءوا به من الباطل، ويعلم بهذا من الغالب، فإن الآدمي أضعف وأحقر من أن يغالب القوي العليم في كيده.","17":"{ فَمَهِّلِ الْكَافِرِينَ أَمْهِلْهُمْ رُوَيْدًا } أي: قليلًا، فسيعلمون عاقبة أمرهم، حين ينزل بهم العقاب.تم تفسير سورة الطارق، والحمد لله رب العالمين."},"87":{"1":"يأمر تعالى بتسبيحه المتضمن لذكره وعبادته، والخضوع لجلاله، والاستكانة لعظمته، وأن يكون تسبيحا، يليق بعظمة الله تعالى، بأن تذكر أسماؤه الحسنى العالية على كل اسم بمعناها الحسن العظيم .","2":"وتذكر أفعاله التي منها أنه خلق المخلوقات فسواها، أي: أتقنها وأحسن خلقها.","3":"{ وَالَّذِي قَدَّرَ } تقديرًا، تتبعه جميع المقدرات { فَهَدَى } إلى ذلك جميع المخلوقات.","4":"وهذه الهداية العامة، التي مضمونها أنه هدى كل مخلوق لمصلحته، وتذكر فيها نعمه الدنيوية، ولهذا قال فيها: { وَالَّذِي أَخْرَجَ الْمَرْعَى } أي: أنزل من السماء ماء فأنبت به أنواع النبات والعشب الكثير، فرتع فيها الناس والبهائم وكل حيوان ، ثم بعد أن استكمل ما قدر له من الشباب، ألوى نباته، وصوح عشبه.","5":"{ فَجَعَلَهُ غُثَاءً أَحْوَى } أي: أسود أي: جعله هشيمًا رميمًا، ويذكر فيها نعمه الدينية.","6":"{ سَنُقْرِئُكَ فَلَا تَنْسَى } أي: سنحفظ ما أوحينا إليك من الكتاب، ونوعيه قلبك، فلا تنسى منه شيئًا، وهذه بشارة كبيرة من الله لعبده ورسوله محمد صلى الله عليه وسلم، أن الله سيعلمه علمًا لا ينساه.","7":"{ إِلَّا مَا شَاءَ اللَّهُ } مما اقتضت حكمته أن ينسيكه لمصلحة بالغة، { إِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفَى } ومن ذلك أنه يعلم ما يصلح عباده أي: فلذلك يشرع ما أراد، ويحكم بما يريد .","8":"{ وَنُيَسِّرُكَ لِلْيُسْرَى } وهذه أيضًا بشارة كبيرة ، أن الله ييسر رسوله صلى الله عليه وسلم لليسرى في جميع أموره، ويجعل شرعه ودينه يسرا .","9":"{ فَذَكِّرْ } بشرع الله وآياته { إِنْ نَفَعَتِ الذِّكْرَى } أي: ما دامت الذكرى مقبولة، والموعظة مسموعة، سواء حصل من الذكرى جميع المقصود أو بعضه.ومفهوم الآية أنه إن لم تنفع الذكرى، بأن كان التذكير يزيد في الشر، أو ينقص من الخير، لم تكن الذكرى مأمورًا بها، بل منهيًا عنها، فالذكرى ينقسم الناس فيها قسمين: منتفعون وغير منتفعين.","10":"فأما المنتفعون، فقد ذكرهم بقوله: { سَيَذَّكَّرُ مَنْ يَخْشَى } الله تعالى، فإن خشية الله تعالى، وعلمه بأن سيجازيه على أعماله ، توجب للعبد الانكفاف عن المعاصي والسعي في الخيرات.","11":"وأما غير المنتفعين، فذكرهم بقوله: { وَيَتَجَنَّبُهَا الْأَشْقَى الَّذِي يَصْلَى النَّارَ الْكُبْرَى } وهي النار الموقدة، التي تطلع على الأفئدة.","12":11,"13":"{ ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَا } أي: يعذب عذابًا أليمًا، من غير راحة ولا استراحة، حتى إنهم يتمنون الموت فلا يحصل لهم، كما قال تعالى: { لَا يُقْضَى عَلَيْهِمْ فَيَمُوتُوا وَلَا يُخَفَّفُ عَنْهُمْ مِنْ عَذَابِهَا } .","14":"{ قَدْ أَفْلَحَ مَنْ تَزَكَّى } أي: قد فاز وربح من طهر نفسه ونقاها من الشرك والظلم ومساوئ الأخلاق.","15":"{ وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى } أي: اتصف بذكر الله، وانصبغ به قلبه، فأوجب له ذلك العمل بما يرضي الله، خصوصًا الصلاة، التي هي ميزان الإيمان، فهذا معنى الآية الكريمة، وأما من فسر قوله { تزكى } بمعني أخرج زكاة الفطر، وذكر اسم ربه فصلى، أنه صلاة العيد، فإنه وإن كان داخلًا في اللفظ وبعض جزئياته، فليس هو المعنى وحده.","16":"{ بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا } أي: تقدمونها على الآخرة، وتختارون نعيمها المنغص المكدر الزائل على الآخرة.","17":"{ وَالْآخِرَةُ خَيْرٌ وَأَبْقَى } وللآخرة خير من الدنيا في كل وصف مطلوب، وأبقى لكونها دار خلد وبقاء وصفاء، والدنيا دار فناء، فالمؤمن العاقل لا يختار الأردأ على الأجود، ولا يبيع لذة ساعة، بترحة الأبد، فحب الدنيا وإيثارها على الآخرة رأس كل خطيئة.","18":"{ إِنَّ هَذَا } المذكور لكم في هذه السورة المباركة، من الأوامر الحسنة، والأخبار المستحسنة { لَفِي الصُّحُفِ الْأُولَى}","19":"[ صُحُفِ إِبْرَاهِيمَ وَمُوسَى } اللذين هما أشرف المرسلين، سوى النبي محمد صلى الله وسلم عليه وسلم.فهذه أوامر في كل شريعة، لكونها عائدة إلى مصالح الدارين، وهي مصالح في كل زمان ومكان.تم تفسير سورة سبح، ولله الحمد"},"88":{"1":"يذكر تعالى أحوال يوم القيامة وما فيها من الأهوال الطامة، وأنها تغشى الخلائق بشدائدها، فيجازون بأعمالهم، ويتميزون إلى فريقين: فريقًا في الجنة، وفريقًا في السعير.","2":"فأخبر عن وصف كلا الفريقين، فقال في [وصف] أهل النار: { وُجُوهٌ يَوْمَئِذٍ } أي: يوم القيامة { خَاشِعَة } من الذل، والفضيحة والخزي.","3":"{ عَامِلَةٌ نَاصِبَةٌ } أي: تاعبة في العذاب، تجر على وجوهها، وتغشى وجوههم النار. ويحتمل أن المراد [بقوله:] { وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ عَامِلَةٌ نَاصِبَةٌ } في الدنيا لكونهم في الدنيا أهل عبادات وعمل، ولكنه لما عدم شرطه وهو الإيمان، صار يوم القيامة هباء منثورا، وهذا الاحتمال وإن كان صحيحًا من حيث المعنى، فلا يدل عليه سياق الكلام، بل الصواب المقطوع به هو الاحتمال الأول، لأنه قيده بالظرف، وهو يوم القيامة، ولأن المقصود هنا بيان وصف أهل النار عمومًا، وذلك الاحتمال جزء قليل من أهل النار بالنسبة إلى أهلها ؛ ولأن الكلام في بيان حال الناس عند غشيان الغاشية، فليس فيه تعرض لأحوالهم في الدنيا.","4":"{ تَصْلَى نَارًا حَامِيَةً } أي: شديدًا حرها، تحيط بهم من كل مكان.","5":"{ تُسْقَى مِنْ عَيْنٍ آنِيَةٍ } أي: حارة شديدة الحرارة { وَإِنْ يَسْتَغِيثُوا يُغَاثُوا بِمَاءٍ كَالْمُهْلِ يَشْوِي الْوُجُوهَ } فهذا شرابهم.","6":"وأما طعامهم فـ { لَيْسَ لَهُمْ طَعَامٌ إِلَّا مِنْ ضَرِيعٍ لَا يُسْمِنُ وَلَا يُغْنِي مِنْ جُوعٍ } وذلك أن المقصود من الطعام أحد أمرين: إما أن يسد جوع صاحبه ويزيل عنه ألمه، وإما أن يسمن بدنه من الهزال، وهذا الطعام ليس فيه شيء من هذين الأمرين، بل هو طعام في غاية المرارة والنتن والخسة نسأل الله العافية.","7":6,"8":"وأما أهل الخير، فوجوههم يوم القيامة { نَاعِمَةٌ } أي: قد جرت عليهم نضرة النعيم، فنضرت أبدانهم، واستنارت وجوههم، وسروا غاية السرور.","9":"{ لِسَعْيِهَا } الذي قدمته في الدنيا من الأعمال الصالحة، والإحسان إلى عباد الله، { رَاضِيَةٍ } إذ وجدت ثوابه مدخرًا مضاعفًا، فحمدت عقباه، وحصل لها كل ما تتمناه.","10":"وذلك أنها { فِي جَنَّةٍ } جامعة لأنواع النعيم كلها، { عَالِيَةٍ } في محلها ومنازلها، فمحلها في أعلى عليين، ومنازلها مساكن عالية، لها غرف ومن فوق الغرف غرف مبنية يشرفون منها على ما أعد الله لهم من الكرامة. { قُطُوفُهَا دَانِيَةٌ } أي: كثيرة الفواكه اللذيذة، المثمرة بالثمار الحسنة، السهلة التناول، بحيث ينالونها على أي: حال كانوا، لا يحتاجون أن يصعدوا شجرة، أو يستعصي عليهم منها ثمرة.","11":"{ لَا تَسْمَعُ فِيهَا } أي: الجنة { لَاغِيَةً } أي: كلمة لغو وباطل، فضلًا عن الكلام المحرم، بل كلامهم كلام حسن [نافع] مشتمل على ذكر الله تعالى، وذكر نعمه المتواترة عليهم، و[على] الآداب المستحسنة بين المتعاشرين، الذي يسر القلوب، ويشرح الصدور.","12":"{ فِيهَا عَيْنٌ جَارِيَةٌ } وهذا اسم جنس أي: فيها العيون الجارية التي يفجرونها ويصرفونها كيف شاءوا، وأنى أرادوا.","13":"{ فِيهَا سُرُرٌ مَرْفُوعَةٌ } و \" السرر \" جمع \" سرير \" وهي المجالس المرتفعة في ذاتها، وبما عليها من الفرش اللينة الوطيئة.","14":"{ وَأَكْوَابٌ مَوْضُوعَةٌ } أي: أوان ممتلئة من أنواع الأشربة اللذيذة، قد وضعت بين أيديهم، وأعدت لهم، وصارت تحت طلبهم واختيارهم، يطوف بها عليهم الولدان المخلدون.","15":"{ وَنَمَارِقُ مَصْفُوفَةٌ } أي: وسائد من الحرير والاستبرق وغيرهما مما لا يعلمه إلا الله، قد صفت للجلوس والاتكاء عليها، وقد أريحوا عن أن يضعوها، و يصفوها بأنفسهم.","16":"{ وَزَرَابِيُّ مَبْثُوثَةٌ } والزرابي [هي:] البسط الحسان، مبثوثة أي: مملوءة بها مجالسهم من كل جانب.","17":"يقول تعالى حثًا للذين لا يصدقون الرسول صلى الله عليه وسلم، ولغيرهم من الناس، أن يتفكروا في مخلوقات الله الدالة على توحيده: { أَفَلَا يَنْظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ } أي: [ألا] ينظرون إلى خلقها البديع، وكيف سخرها الله للعباد، وذللها لمنافعهم الكثيرة التي يضطرون إليها.","18":17,"19":"{ وَإِلَى الْجِبَالِ كَيْفَ نُصِبَتْ } بهيئة باهرة، حصل بها استقرار الأرض وثباتها عن الاضطراب، وأودع فيها من المنافع [الجليلة] ما أودع.","20":"{ وَإِلَى الْأَرْضِ كَيْفَ سُطِحَتْ } أي: مدت مدًا واسعًا، وسهلت غاية التسهيل، ليستقر الخلائق على ظهرها، ويتمكنوا من حرثها وغراسها، والبنيان فيها، وسلوك الطرق الموصلة إلى أنواع المقاصد فيها. واعلم أن تسطيحها لا ينافي أنها كرة مستديرة، قد أحاطت الأفلاك فيها من جميع جوانبها، كما دل على ذلك النقل والعقل والحس والمشاهدة، كما هو مذكور معروف عند أكثر الناس، خصوصًا في هذه الأزمنة، التي وقف الناس على أكثر أرجائها بما أعطاهم الله من الأسباب المقربة للبعيد، فإن التسطيح إنما ينافي كروية الجسم الصغير جدًا، الذي لو سطح لم يبق له استدارة تذكر. وأما جسم الأرض الذي هو في غاية الكبر والسعة ، فيكون كرويًا مسطحًا، ولا يتنافى الأمران، كما يعرف ذلك أرباب الخبرة.","21":"{ فَذَكِّرْ إِنَّمَا أَنْتَ مُذَكِّرٌ } أي: ذكر الناس وعظهم، وأنذرهم وبشرهم، فإنك مبعوث لدعوة الخلق إلى الله وتذكيرهم.","22":"ولم تبعث مسيطرًا عليهم، مسلطًا موكلًا بأعمالهم، فإذا قمت بما عليك، فلا عليك بعد ذلك لوم، كقوله تعالى: { وَمَا أَنْتَ عَلَيْهِمْ بِجَبَّارٍ فَذَكِّرْ بِالْقُرْآنِ مَنْ يَخَافُ وَعِيدِ } .","23":"{ إِلَّا مَنْ تَوَلَّى وَكَفَرَ } أي: لكن من تولى عن الطاعة وكفر بالله","24":"{ فَيُعَذِّبُهُ اللَّهُ الْعَذَابَ الْأَكْبَرَ } أي: الشديد الدائم،","25":"{ إِنَّ إِلَيْنَا إِيَابَهُمْ } أي: رجوع الخليقة وجمعهم في يوم القيامة.","26":"{ ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُمْ } فنحاسبهم على ما عملوا من خير وشر. آخر تفسير سورة الغاشية، والحمد لله رب العالمين"},"89":{"1":"الظاهر أن المقسم به، هو المقسم عليه، وذلك جائز مستعمل، إذا كان أمرًا ظاهرًا مهمًا، وهو كذلك في هذا الموضع.فأقسم تعالى بالفجر، الذي هو آخر الليل ومقدمة النهار، لما في إدبار الليل وإقبال النهار، من الآيات الدالة على كمال قدرة الله تعالى، وأنه وحده المدبر لجميع الأمور، الذي لا تنبغي العبادة إلا له، ويقع في الفجر صلاة فاضلة معظمة، يحسن أن يقسم الله بها، ولهذا أقسم بعده بالليالي العشر، وهي على الصحيح: ليالي عشر رمضان، أو [عشر] ذي الحجة، فإنها ليال مشتملة على أيام فاضلة، ويقع فيها من العبادات والقربات ما لا يقع في غيرها.","2":"وفي ليالي عشر رمضان ليلة القدر، التي هي خير من ألف شهر، وفي نهارها، صيام آخر رمضان الذي هو ركن من أركان الإسلام.وفي أيام عشر ذي الحجة، الوقوف بعرفة، الذي يغفر الله فيه لعباده مغفرة يحزن لها الشيطان، فما رئي الشيطان أحقر ولا أدحر منه في يوم عرفة، لما يرى من تنزل الأملاك والرحمة من الله لعباده، ويقع فيها كثير من أفعال الحج والعمرة، وهذه أشياء معظمة، مستحقة لأن يقسم الله بها.","3":2,"4":"{ وَاللَّيْلِ إِذَا يَسْرِ } أي: وقت سريانه وإرخائه ظلامه على العباد، فيسكنون ويستريحون ويطمئنون، رحمة منه تعالى وحكمة.","5":"{ هَلْ فِي ذَلِكَ } المذكور { قَسَمٌ لِذِي حِجْرٍ } أي: [لذي] عقل؟ نعم، بعض ذلك يكفي، لمن كان له قلب أو ألقى السمع وهو شهيد.","6":"يقول تعالى: { أَلَمْ تَرَ } بقلبك وبصيرتك كيف فعل بهذه الأمم الطاغية","7":"{ إِرَمَ } القبيلة المعروفة في اليمن { ذَاتِ الْعِمَادِ } أي: القوة الشديدة، والعتو والتجبر.","8":"{ الَّتِي لَمْ يُخْلَقْ مِثْلُهَا } أي: مثل عاد { فِي الْبِلَادِ } أي: في جميع البلدان [في القوة والشدة]، كما قال لهم نبيهم هود عليه السلام: { وَاذْكُرُوا إِذْ جَعَلَكُمْ خُلَفَاءَ مِنْ بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِي الْخَلْقِ بَسْطَةً فَاذْكُرُوا آلَاءَ اللَّهِ لَعَلَّكُمْ تُفْلِحُونَ } .","9":"{ وَثَمُودَ الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِ } أي: وادي القرى، نحتوا بقوتهم الصخور، فاتخذوها مساكن.","10":"{ وَفِرْعَوْنَ ذِي الْأَوْتَاد } أي: [ذي] الجنود الذين ثبتوا ملكه، كما تثبت الأوتاد ما يراد إمساكه بها.","11":"{ الَّذِينَ طَغَوْا فِي الْبِلَادِ } هذا الوصف عائد إلى عاد وثمود وفرعون ومن تبعهم، فإنهم طغوا في بلاد الله، وآذوا عباد الله، في دينهم ودنياهم، ولهذا قال:","12":"{ فَأَكْثَرُوا فِيهَا الْفَسَادَ } وهو العمل بالكفر وشعبه، من جميع أجناس المعاصي، وسعوا في محاربة الرسل وصد الناس عن سبيل الله.","13":"فلما بلغوا من العتو ما هو موجب لهلاكهم، أرسل الله عليهم من عذابه ذنوبًا وسوط عذاب.","14":"{ إِنَّ رَبَّكَ لَبِالْمِرْصَادِ } لمن عصاه يمهله قليلًا، ثم يأخذه أخذ عزيز مقتدر.","15":"يخبر تعالى عن طبيعة الإنسان من حيث هو، وأنه جاهل ظالم، لا علم له بالعواقب، يظن الحالة التي تقع فيه تستمر ولا تزول، ويظن أن إكرام الله في الدنيا وإنعامه عليه يدل على كرامته عنده وقربه منه.","16":"وأنه إذا { قدر عَلَيْهِ رِزْقُهُ } أي: ضيقه، فصار يقدر قوته لا يفضل منه، أن هذا إهانة من الله له.","17":"فرد الله عليه هذا الحسبان: بقوله { كَلَّا } أي: ليس كل من نعمته في الدنيا فهو كريم علي، ولا كل من قدرت عليه رزقه فهو مهان لدي، وإنما الغنى والفقر، والسعة والضيق، ابتلاء من الله، وامتحان يمتحن به العباد، ليرى من يقوم له بالشكر والصبر، فيثيبه على ذلك الثواب الجزيل، ممن ليس كذلك فينقله إلى العذاب الوبيل.وأيضًا، فإن وقوف همة العبد عند مراد نفسه فقط، من ضعف الهمة، ولهذا لامهم الله على عدم اهتمامهم بأحوال الخلق المحتاجين، فقال: { كَلَّا بَل لَا تُكْرِمُونَ الْيَتِيمَ } الذي فقد أباه وكاسبه، واحتاج إلى جبر خاطره والإحسان إليه.فأنتم لا تكرمونه بل تهينونه، وهذا يدل على عدم الرحمة في قلوبكم، وعدم الرغبة في الخير.","18":"{ وَلَا تَحَاضُّونَ عَلَى طَعَامِ الْمِسْكِين } أي: لا يحض بعضكم بعضًا على إطعام المحاويج من المساكين والفقراء، وذلك لأجل الشح على الدنيا ومحبتها الشديدة المتمكنة من القلوب.","19":"{ وَتَأْكُلُونَ التُّرَاثَ } أي: المال المخلف { أَكْلًا لَمًّا } أي: ذريعًا، لا تبقون على شيء منه.","20":"{ وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا } أي: كثيرًا شديدًا، وهذا كقوله تعالى: { بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا وَالْآخِرَةُ خَيْرٌ وَأَبْقَى } { كَلَّا بَلْ تُحِبُّونَ الْعَاجِلَةَ وَتَذَرُونَ الْآخِرَةَ } .","21":"{ كَلَّا } أي: ليس [كل] ما أحببتم من الأموال، وتنافستم فيه من اللذات، بباق لكم، بل أمامكم يوم عظيم، وهول جسيم، تدك فيه الأرض والجبال وما عليها حتى تجعل قاعًا صفصفًا لا عوج فيه ولا أمت.","22":"ويجيء الله تعالى لفصل القضاء بين عباده في ظلل من الغمام، وتجيء الملائكة الكرام، أهل السماوات كلهم، صفًا صفا أي: صفًا بعد صف، كل سماء يجيء ملائكتها صفا، يحيطون بمن دونهم من الخلق، وهذه الصفوف صفوف خضوع وذل للملك الجبار.","23":"{ وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ } تقودها الملائكة بالسلاسل.فإذا وقعت هذه الأمور فـ { يَوْمَئِذٍ يَتَذَكَّرُ الْإِنْسَانُ } ما قدمه من خير وشر.{ وَأَنَّى لَهُ الذِّكْرَى } فقد فات أوانها، وذهب زمانها.","24":"يقول متحسرًا على ما فرط في جنب الله: { يَا لَيْتَنِي قَدَّمْتُ لِحَيَاتِي } الدائمة الباقية، عملًا صالحًا، كما قال تعالى: { يَقُولُ يَا لَيْتَنِي اتَّخَذْتُ مَعَ الرَّسُولِ سَبِيلًا يَا وَيْلَتَى لَيْتَنِي لَمْ أَتَّخِذْ فُلَانًا خَلِيلًا } . وفي الآية دليل على أن الحياة التي ينبغي السعي في أصلها وكمالها ، وفي تتميم لذاتها، هي الحياة في دار القرار، فإنها دار الخلد والبقاء.","25":"{ فَيَوْمَئِذٍ لَا يُعَذِّبُ عَذَابَهُ أَحَدٌ } لمن أهمل ذلك اليوم ونسي العمل له.","26":"{ وَلَا يُوثِقُ وَثَاقَهُ أَحَدٌ } فإنهم يقرنون بسلاسل من نار، ويسحبون على وجوههم في الحميم، ثم في النار يسجرون، فهذا جزاء المجرمين.","27":"وأما من اطمأن إلى الله وآمن به وصدق رسله، فيقال له: { يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ } إلى ذكر الله، الساكنة [إلى] حبه، التي قرت عينها بالله.","28":"{ ارْجِعِي إِلَى رَبِّكِ } الذي رباك بنعمته، وأسدى عليك من إحسانه ما صرت به من أوليائه وأحبابه { رَاضِيَةً مَرْضِيَّةً } أي: راضية عن الله، وعن ما أكرمها به من الثواب، والله قد رضي عنها.","29":"{ فَادْخُلِي فِي عِبَادِي وَادْخُلِي جَنَّتِي } وهذا تخاطب به الروح يوم القيامة، وتخاطب به حال الموت [والحمد لله رب العالمين].","30":29},"90":{"1":"يقسم تعالى { بِهَذَا الْبَلَدِ } الأمين، الذي هو مكة المكرمة، أفضل البلدان على الإطلاق، خصوصًا وقت حلول الرسول صلى الله عليه وسلم فيها.","2":"خصوصا وقت حلول الرسول صلى الله عليه وسلم فيها","3":"{ وَوَالِدٍ وَمَا وَلَدَ } أي: آدم وذريته.","4":"والمقسم عليه قوله: { لَقَدْ خَلَقْنَا الْإِنْسَانَ فِي كَبَدٍ } يحتمل أن المراد بذلك ما يكابده ويقاسيه من الشدائد في الدنيا، وفي البرزخ، ويوم يقوم الأشهاد، وأنه ينبغي له أن يسعى في عمل يريحه من هذه الشدائد، ويوجب له الفرح والسرور الدائم.وإن لم يفعل، فإنه لا يزال يكابد العذاب الشديد أبد الآباد.ويحتمل أن المعنى: لقد خلقنا الإنسان في أحسن تقويم، وأقوم خلقة، مقدر على التصرف والأعمال الشديدة، ومع ذلك، [فإنه] لم يشكر الله على هذه النعمة [العظيمة]، بل بطر بالعافية وتجبر على خالقه، فحسب بجهله وظلمه أن هذه الحال ستدوم له، وأن سلطان تصرفه لا ينعزل،","5":"{ أَيَحْسَبُ أَنْ لَنْ يَقْدِرَ عَلَيْهِ أَحَدٌ } ويطغى ويفتخر بما أنفق من الأموال على شهوات نفسه.","6":"فـ { يَقُولُ أَهْلَكْتُ مَالًا لُبَدًا } أي: كثيًرا، بعضه فوق بعض.وسمى الله تعالى الإنفاق في الشهوات والمعاصي إهلاكًا، لأنه لا ينتفع المنفق بما أنفق، ولا يعود عليه من إنفاقه إلا الندم والخسار والتعب والقلة، لا كمن أنفق في مرضاة الله في سبيل الخير، فإن هذا قد تاجر مع الله، وربح أضعاف أضعاف ما أنفق.","7":"قال الله متوعدًا هذا الذي يفتخر بما أنفق في الشهوات: { أَيَحْسَبُ أَنْ لَمْ يَرَهُ أَحَدٌ } أي: أيحسب في فعله هذا، أن الله لا يراه ويحاسبه على الصغير والكبير؟بل قد رآه الله، وحفظ عليه أعماله، ووكل به الكرام الكاتبين، لكل ما عمله من خير وشر.","8":"ثم قرره بنعمه، فقال: { أَلَمْ نَجْعَلْ لَهُ عَيْنَيْنِ وَلِسَانًا وَشَفَتَيْنِ } للجمال والبصر والنطق، وغير ذلك من المنافع الضرورية فيها، فهذه نعم الدنيا.","9":8,"10":"ثم قال في نعم الدين: { وَهَدَيْنَاهُ النَّجْدَيْن } أي: طريقي الخير والشر، بينا له الهدى من الضلال، والرشد من الغي.فهذه المنن الجزيلة، تقتضي من العبد أن يقوم بحقوق الله، ويشكر الله على نعمه، وأن لا يستعين بها على معاصيه ، ولكن هذا الإنسان لم يفعل ذلك.","11":"{ فَلَا اقْتَحَمَ الْعَقَبَةَ } أي: لم يقتحمها ويعبر عليها، لأنه متبع لشهواته .","12":"وهذه العقبة شديدة عليه","13":"وهذه العقبة شديدة عليه، ثم فسر [هذه] العقبة { فَكُّ رَقَبَةٍ } أي: فكها من الرق، بعتقها أو مساعدتها على أداء كتابتها، ومن باب أولى فكاك الأسير المسلم عند الكفار.","14":"{ أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ } أي: مجاعة شديدة، بأن يطعم وقت الحاجة أشد الناس حاجة.","15":"{ يَتِيمًا ذَا مَقْرَبَةٍ } أي: جامعًا بين كونه يتيمًا، فقيرًا ذا قرابة.","16":"{ أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ } أي: قد لزق بالتراب من الحاجة والضرورة.","17":"{ ثُمَّ كَانَ مِنَ الَّذِينَ آمَنُوا } أي: آمنوا بقلوبهم بما يجب الإيمان به، وعملوا الصالحات بجوارحهم. من كل قول وفعل واجب أو مستحب. { وَتَوَاصَوْا بِالصَّبْرِ } على طاعة الله وعن معصيته، وعلى أقدار المؤلمة بأن يحث بعضهم بعضًا على الانقياد لذلك، والإتيان به كاملًا منشرحًا به الصدر، مطمئنة به النفس.{ وَتَوَاصَوْا بِالْمَرْحَمَةِ } للخلق، من إعطاء محتاجهم، وتعليم جاهلهم، والقيام بما يحتاجون إليه من جميع الوجوه، ومساعدتهم على المصالح الدينية والدنيوية، وأن يحب لهم ما يحب لنفسه، ويكره لهم ما يكره لنفسه.","18":"أولئك الذين قاموا بهذه الأوصاف، الذين وفقهم الله لاقتحام هذه العقبة { أُولَئِكَ أَصْحَابُ الْمَيْمَنَةِ } لأنهم أدوا ما أمر الله به من حقوقه وحقوق عباده، وتركوا ما نهوا عنه، وهذا عنوان السعادة وعلامتها.","19":"{ وَالَّذِينَ كَفَرُوا بِآيَاتِنَا } بأن نبذوا هذه الأمور وراء ظهورهم، فلم يصدقوا بالله، [ولا آمنوا به]، ولا عملوا صالحًا، ولا رحموا عباد الله، { والذين كفروا بآياتنا همْ أَصْحَابُ الْمَشْئَمَة}","20":"[عَلَيْهِمْ نَارٌ مُؤْصَدَةٌ } أي: مغلقة، في عمد ممددة، قد مدت من ورائها، لئلا تنفتح أبوابها، حتى يكونوا في ضيق وهم وشدة [والحمد لله]."},"91":{"1":"أقسم تعالى بهذه الآيات العظيمة، على النفس المفلحة، وغيرها من النفوس الفاجرة، فقال:{ وَالشَّمْسِ وَضُحَاهَا } أي: نورها، ونفعها الصادر منها.","2":"{ وَالْقَمَرِ إِذَا تَلَاهَا } أي: تبعها في المنازل والنور.","3":"{ وَالنَّهَارِ إِذَا جَلَّاهَا } أي: جلى ما على وجه الأرض وأوضحه.","4":"{ وَاللَّيْلِ إِذَا يَغْشَاهَا } أي: يغشى وجه الأرض، فيكون ما عليها مظلمًا.فتعاقب الظلمة والضياء، والشمس والقمر، على هذا العالم، بانتظام وإتقان، وقيام لمصالح العباد، أكبر دليل على أن الله بكل شيء عليم، وعلى كل شيء قدير، وأنه المعبود وحده، الذي كل معبود سواه فباطل.","5":"{ وَالسَّمَاءِ وَمَا بَنَاهَا } يحتمل أن \\\" ما \\\" موصولة، فيكون الإقسام بالسماء وبانيها، الذي هو الله تبارك وتعالى، ويحتمل أنها مصدرية، فيكون الإقسام بالسماء وبنيانها، الذي هو غاية ما يقدر من الإحكام والإتقان والإحسان.","6":"{ وَالْأَرْضِ وَمَا طَحَاهَا } أي: مدها ووسعها، فتمكن الخلق حينئذ من الانتفاع بها، بجميع وجوه الانتفاع.","7":"{ وَنَفْسٍ وَمَا سَوَّاهَا } يحتمل أن المراد نفس سائر المخلوقات الحيوانية، كما يؤيد هذا العموم، ويحتمل أن المراد بالإقسام بنفس الإنسان المكلف، بدليل ما يأتي بعده.وعلى كل، فالنفس آية كبيرة من آياته التي حقيقة بالإقسام بها فإنها في غاية اللطف والخفة، سريعة التنقل [والحركة] والتغير والتأثر والانفعالات النفسية، من الهم، والإرادة، والقصد، والحب، والبغض، وهي التي لولاها لكان البدن مجرد تمثال لا فائدة فيه، وتسويتها على هذا الوجه آية من آيات الله العظيمة.","8":7,"9":"وقوله: { قَدْ أَفْلَحَ مَنْ زَكَّاهَا } أي: طهر نفسه من الذنوب، ونقاها من العيوب، ورقاها بطاعة الله، وعلاها بالعلم النافع والعمل الصالح.","10":"{ وَقَدْ خَابَ مَنْ دَسَّاهَا } أي: أخفى نفسه الكريمة، التي ليست حقيقة بقمعها وإخفائها، بالتدنس بالرذائل، والدنو من العيوب، والاقتراف للذنوب، وترك ما يكملها وينميها، واستعمال ما يشينها ويدسيها.","11":"{ كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا } أي: بسبب طغيانها وترفعها عن الحق، وعتوها على رسل الله","12":"{ إِذِ انْبَعَثَ أَشْقَاهَا } أي: أشقى القبيلة، وهو \" قدار بن سالف \" لعقرها حين اتفقوا على ذلك، وأمروه فأتمر لهم.","13":"{ فَقَالَ لَهُمْ رَسُولُ اللَّهِ } صالح عليه السلام محذرًا: { نَاقَةَ اللَّهِ وَسُقْيَاهَا } أي: احذروا عقر ناقة الله، التي جعلها لكم آية عظيمة، ولا تقابلوا نعمة الله عليكم بسقي لبنها أن تعقروها، فكذبوا نبيهم صالحًا.","14":"{ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ بِذَنْبِهِمْ } أي: دمر عليهم وعمهم بعقابه، وأرسل عليهم الصيحة من فوقهم، والرجفة من تحتهم، فأصبحوا جاثمين على ركبهم، لا تجد منهم داعيًا ولا مجيبا.{ فَسَوَّاهَا } عليهم أي: سوى بينهم بالعقوبة","15":"{ وَلَا يَخَافُ عُقْبَاهَا } أي: تبعتها.وكيف يخاف من هو قاهر، لا يخرج عن قهره وتصرفه مخلوق، الحكيم في كل ما قضاه وشرعه؟تمت ولله الحمد"},"92":{"1":"هذا قسم من الله بالزمان الذي تقع فيه أفعال العباد على تفاوت أحوالهم، فقال: { وَاللَّيْلِ إِذَا يَغْشَى } أي: يعم الخلق بظلامه، فيسكن كل إلى مأواه ومسكنه، ويستريح العباد من الكد والتعب.","2":"{ وَالنَّهَارِ إِذَا تَجَلَّى } للخلق، فاستضاءوا بنوره، وانتشروا في مصالحهم.","3":"{ وَمَا خَلَقَ الذَّكَرَ وَالْأُنْثَى } إن كانت \" ما \" موصولة، كان إقسامًا بنفسه الكريمة الموصوفة، بأنه خالق الذكور والإناث، وإن كانت مصدرية، كان قسمًا بخلقه للذكر والأنثى، وكمال حكمته في ذلك أن خلق من كل صنف من الحيوانات التي يريد بقاءها ذكرًا وأنثى، ليبقى النوع ولا يضمحل، وقاد كلا منهما إلى الآخر بسلسلة الشهوة، وجعل كلًا منهما مناسبًا للآخر، فتبارك الله أحسن الخالقين.","4":"{ إِنَّ سَعْيَكُمْ لَشَتَّى } هذا [هو] المقسم عليه أي: إن سعيكم أيها المكلفون لمتفاوت تفاوتا كثيًرا، وذلك بحسب تفاوت نفس الأعمال ومقدارها والنشاط فيها، وبحسب الغاية المقصودة بتلك الأعمال، هل هو وجه الله الأعلى الباقي؟ فيبقى السعي له ببقائه، وينتفع به صاحبه، أم هي غاية مضمحلة فانية، فيبطل السعي ببطلانها، ويضمحل باضمحلالها؟","5":"فصل الله تعالى العاملين، ووصف أعمالهم، فقال: { فَأَمَّا مَنْ أَعْطَى } [أي] ما أمر به من العبادات المالية، كالزكوات، والكفارات والنفقات، والصدقات، والإنفاق في وجوه الخير، والعبادات البدنية كالصلاة، والصوم ونحوهما. والمركبة منهما، كالحج والعمرة [ونحوهما] { وَاتَّقَى } ما نهي عنه، من المحرمات والمعاصي، على اختلاف أجناسها.","6":"{ وَصَدَّقَ بِالْحُسْنَى } أي: صدق بـ \" لا إله إلا الله \" وما دلت عليه، من جميع العقائد الدينية، وما ترتب عليها من الجزاء الأخروي.","7":"{ فَسَنُيَسِّرُهُ لِلْيُسْرَى } أي: نسهل عليه أمره، ونجعله ميسرا له كل خير، ميسرًا له ترك كل شر، لأنه أتى بأسباب التيسير، فيسر الله له ذلك.","8":"{ وَأَمَّا مَنْ بَخِلَ } بما أمر به، فترك الإنفاق الواجب والمستحب، ولم تسمح نفسه بأداء ما وجب لله، { وَاسْتَغْنَى } عن الله، فترك عبوديته جانبًا، ولم ير نفسه مفتقرة غاية الافتقار إلى ربها، الذي لا نجاة لها ولا فوز ولا فلاح، إلا بأن يكون هو محبوبها ومعبودها، الذي تقصده وتتوجه إليه.","9":"{ وَكَذَّبَ بِالْحُسْنَى } أي: بما أوجب الله على العباد التصديق به من العقائد الحسنة.","10":"{ فَسَنُيَسِّرُهُ لِلْعُسْرَى } أي: للحالة العسرة، والخصال الذميمة، بأن يكون ميسرًا للشر أينما كان، ومقيضًا له أفعال المعاصي، نسأل الله العافية.","11":"{ وَمَا يُغْنِي عَنْهُ مَالُهُ } الذي أطغاه واستغنى به، وبخل به إذا هلك ومات، فإنه لا يصحبه إلا عمله الصالح .وأما ماله [الذي لم يخرج منه الواجب] فإنه يكون وبالًا عليه، إذ لم يقدم منه لآخرته شيئًا.","12":"{ إِنَّ عَلَيْنَا لَلْهُدَى } أي: إن الهدى المستقيم طريقه، يوصل إلى الله، ويدني من رضاه، وأما الضلال، فطرق مسدودة عن الله، لا توصل صاحبها إلا للعذاب الشديد.","13":"{ وَإِنَّ لَنَا لَلْآخِرَةَ وَالْأُولَى } ملكًا وتصرفًا، ليس له فيهما مشارك، فليرغب الراغبون إليه في الطلب، ولينقطع رجاؤهم عن المخلوقين.","14":"{ فَأَنْذَرْتُكُمْ نَارًا تَلَظَّى } أي: تستعر وتتوقد.","15":"{ لَا يَصْلَاهَا إِلَّا الْأَشْقَى الَّذِي كَذَّبَ } بالخبر { وَتَوَلَّى } عن الأمر.","16":15,"17":"{ وَسَيُجَنَّبُهَا الْأَتْقَى الَّذِي يُؤْتِي مَالَهُ يَتَزَكَّى } بأن يكون قصده به تزكية نفسه، وتطهيرها من الذنوب والعيوب ، قاصدًا به وجه الله تعالى، فدل هذا على أنه إذا تضمن الإنفاق المستحب ترك واجب، كدين ونفقة ونحوهما، فإنه غير مشروع، بل تكون عطيته مردودة عند كثير من العلماء، لأنه لا يتزكى بفعل مستحب يفوت عليه الواجب.","18":17,"19":"{ وَمَا لِأَحَدٍ عِنْدَهُ مِنْ نِعْمَةٍ تُجْزَى } أي: ليس لأحد من الخلق على هذا الأتقى نعمة تجزى إلا وقد كافأه بها، وربما بقي له الفضل والمنة على الناس، فتمحض عبدًا لله، لأنه رقيق إحسانه وحده، وأما من بقي عليه نعمة للناس لم يجزها ويكافئها، فإنه لا بد أن يترك للناس، ويفعل لهم ما ينقص [إخلاصه].وهذه الآية، وإن كانت متناولة لأبي بكر الصديق رضي الله عنه، بل قد قيل إنها نزلت في سببه، فإنه -رضي الله عنه- ما لأحد عنده من نعمة تجزى، حتى ولا رسول الله صلى الله عليه وسلم، إلا نعمة الرسول التي لا يمكن جزاؤها، وهي [نعمة] الدعوة إلى دين الإسلام، وتعليم الهدى ودين الحق، فإن لله ورسوله المنة على كل أحد، منة لا يمكن لها جزاء ولا مقابلة، فإنها متناولة لكل من اتصف بهذا الوصف الفاضل، فلم يبق لأحد عليه من الخلق نعمة تجزى، فبقيت أعماله خالصة لوجه الله تعالى.","20":"{ إِلَّا ابْتِغَاءَ وَجْهِ رَبِّهِ الْأَعْلَى وَلَسَوْفَ يَرْضَى } هذا الأتقى بما يعطيه الله من أنواع الكرامات والمثوبات، والحمد لله رب العالمين.","21":20},"93":{"1":"أقسم تعالى بالنهار إذا انتشر ضياؤه بالضحى.","2":"وبالليل إذا سجى وادلهمت ظلمته، على اعتناء الله برسوله صلى الله عليه وسلم","3":"{ مَا وَدَّعَكَ رَبُّكَ } أي: ما تركك منذ اعتنى بك، ولا أهملك منذ رباك ورعاك، بل لم يزل يربيك أحسن تربية، ويعليك درجة بعد درجة. { وَمَا قَلا } ك الله أي: ما أبغضك منذ أحبك، فإن نفي الضد دليل على ثبوت ضده، والنفي المحض لا يكون مدحًا، إلا إذا تضمن ثبوت كمال، فهذه حال الرسول صلى الله عليه وسلم الماضية والحاضرة، أكمل حال وأتمها، محبة الله له واستمرارها، وترقيته في درج الكمال، ودوام اعتناء الله به.","4":"وأما حاله المستقبلة، فقال: { وَلَلْآخِرَةُ خَيْرٌ لَكَ مِنَ الْأُولَى } أي: كل حالة متأخرة من أحوالك، فإن لها الفضل على الحالة السابقة. فلم يزل صلى الله عليه وسلم يصعد في درج المعالي ويمكن له الله دينه، وينصره على أعدائه، ويسدد له أحواله، حتى مات، وقد وصل إلى حال لا يصل إليها الأولون والآخرون، من الفضائل والنعم، وقرة العين، وسرور القلب.","5":"ثم بعد ذلك، لا تسأل عن حاله في الآخرة، من تفاصيل الإكرام، وأنواع الإنعام، ولهذا قال: { وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى } وهذا أمر لا يمكن التعبير عنه بغير هذه العبارة الجامعة الشاملة. ثم امتن عليه بما يعلمه من أحواله [الخاصة] فقال:","6":"{ أَلَمْ يَجِدْكَ يَتِيمًا فَآوَى } أي: وجدك لا أم لك، ولا أب، بل قد مات أبوه وأمه وهو لا يدبر نفسه، فآواه الله، وكفله جده عبد المطلب، ثم لما مات جده كفله الله عمه أبا طالب، حتى أيده بنصره وبالمؤمنين.","7":"{ وَوَجَدَكَ ضَالًّا فَهَدَى } أي: وجدك لا تدري ما الكتاب ولا الإيمان، فعلمك ما لم تكن تعلم، ووفقك لأحسن الأعمال والأخلاق.","8":"{ وَوَجَدَكَ عَائِلًا } أي: فقيرًا { فَأَغْنَى } بما فتح الله عليك من البلدان، التي جبيت لك أموالها وخراجها. فالذي أزال عنك هذه النقائص، سيزيل عنك كل نقص، والذي أوصلك إلى الغنى، وآواك ونصرك وهداك، قابل نعمته بالشكران.","9":"{ فَأَمَّا الْيَتِيمَ فَلَا تَقْهَرْ } أي: لا تسيء معاملة اليتيم، ولا يضق صدرك عليه، ولا تنهره، بل أكرمه، وأعطه ما تيسر، واصنع به كما تحب أن يصنع بولدك من بعدك.","10":"{ وَأَمَّا السَّائِلَ فَلَا تَنْهَرْ } أي: لا يصدر منك إلى السائل كلام يقتضي رده عن مطلوبه، بنهر وشراسة خلق، بل أعطه ما تيسر عندك أو رده بمعروف [وإحسان]. وهذا يدخل فيه السائل للمال، والسائل للعلم، ولهذا كان المعلم مأمورًا بحسن الخلق مع المتعلم، ومباشرته بالإكرام والتحنن عليه، فإن في ذلك معونة له على مقصده، وإكرامًا لمن كان يسعى في نفع العباد والبلاد.","11":"{ وَأَمَّا بِنِعْمَةِ رَبِّكَ } [وهذا يشمل] النعم الدينية والدنيوية { فَحَدِّثْ } أي: أثن على الله بها، وخصصها بالذكر إن كان هناك مصلحة. وإلا فحدث بنعم الله على الإطلاق، فإن التحدث بنعمة الله، داع لشكرها، وموجب لتحبيب القلوب إلى من أنعم بها، فإن القلوب مجبولة على محبة المحسن."},"94":{"1":"يقول تعالى -ممتنًا على رسوله-: { أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ } أي: نوسعه لشرائع الدين والدعوة إلى الله، والاتصاف بمكارم الأخلاق، والإقبال على الآخرة، وتسهيل الخيرات فلم يكن ضيقًا حرجًا، لا يكاد ينقاد لخير، ولا تكاد تجده منبسطًا.","2":"{ وَوَضَعْنَا عَنْكَ وِزْرَكَ } أي: ذنبك،","3":"{ الَّذِي أَنْقَضَ } أي: أثقل { ظَهْرَكَ } كما قال تعالى: { لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ } .","4":"{ وَرَفَعْنَا لَكَ ذِكْرَكَ } أي: أعلينا قدرك، وجعلنا لك الثناء الحسن العالي، الذي لم يصل إليه أحد من الخلق، فلا يذكر الله إلا ذكر معه رسوله صلى الله عليه وسلم، كما في الدخول في الإسلام، وفي الأذان، والإقامة، والخطب، وغير ذلك من الأمور التي أعلى الله بها ذكر رسوله محمد صلى الله عليه وسلم.وله في قلوب أمته من المحبة والإجلال والتعظيم ما ليس لأحد غيره، بعد الله تعالى، فجزاه الله عن أمته أفضل ما جزى نبيًا عن أمته.","5":"{ فَإِنَّ مَعَ الْعُسْرِ يُسْرًا إِنَّ مَعَ الْعُسْرِ يُسْرًا } بشارة عظيمة، أنه كلما وجد عسر وصعوبة، فإن اليسر يقارنه ويصاحبه، حتى لو دخل العسر جحر ضب لدخل عليه اليسر، فأخرجه كما قال تعالى: { سَيَجْعَلُ اللَّهُ بَعْدَ عُسْرٍ يُسْرًا } وكما قال النبي صلى الله عليه وسلم: \\\" وإن الفرج مع الكرب، وإن مع العسر يسرا \\\" .وتعريف \\\" العسر \\\" في الآيتين، يدل على أنه واحد، وتنكير \\\" اليسر \\\" يدل على تكراره، فلن يغلب عسر يسرين.وفي تعريفه بالألف واللام، الدالة على الاستغراق والعموم يدل على أن كل عسر -وإن بلغ من الصعوبة ما بلغ- فإنه في آخره التيسير ملازم له.","6":"{ فَإِنَّ مَعَ الْعُسْرِ يُسْرًا إِنَّ مَعَ الْعُسْرِ يُسْرًا } بشارة عظيمة، أنه كلما وجد عسر وصعوبة، فإن اليسر يقارنه ويصاحبه، حتى لو دخل العسر جحر ضب لدخل عليه اليسر، فأخرجه كما قال تعالى: { سَيَجْعَلُ اللَّهُ بَعْدَ عُسْرٍ يُسْرًا } وكما قال النبي صلى الله عليه وسلم: \\\" وإن الفرج مع الكرب، وإن مع العسر يسرا \\\" .وتعريف \\\" العسر \\\" في الآيتين، يدل على أنه واحد، وتنكير \\\" اليسر \\\" يدل على تكراره، فلن يغلب عسر يسرين.وفي تعريفه بالألف واللام، الدالة على الاستغراق والعموم يدل على أن كل عسر -وإن بلغ من الصعوبة ما بلغ- فإنه في آخره التيسير ملازم له","7":"ثم أمر الله رسوله أصلًا، والمؤمنين تبعًا، بشكره والقيام بواجب نعمه، فقال: { فَإِذَا فَرَغْتَ فَانْصَبْ } أي: إذا تفرغت من أشغالك، ولم يبق في قلبك ما يعوقه، فاجتهد في العبادة والدعاء.","8":"{ وَإِلَى رَبِّكَ } وحده { فَارْغَبْ } أي: أعظم الرغبة في إجابة دعائك وقبول عباداتك .ولا تكن ممن إذا فرغوا وتفرغوا لعبوا وأعرضوا عن ربهم وعن ذكره، فتكون من الخاسرين.وقد قيل: إن معنى قوله: فإذا فرغت من الصلاة وأكملتها، فانصب في الدعاء، وإلى ربك فارغب في سؤال مطالبك.واستدل من قال بهذا القول، على مشروعية الدعاء والذكر عقب الصلوات المكتوبات، والله أعلم بذلك تمت ولله الحمد."},"95":{"1":"(التين) هو التين المعروف، وكذلك { الزَّيْتُونَ } أقسم بهاتين الشجرتين، لكثرة منافع شجرهما وثمرهما، ولأن سلطانهما في أرض الشام، محل نبوة عيسى ابن مريم عليه السلام.","2":"{ وَطُورِ سِينِينَ } أي: طور سيناء، محل نبوة موسى صلى الله عليه وسلم.","3":"{ وَهَذَا الْبَلَدِ الْأَمِينِ } وهي: مكة المكرمة، محل نبوة محمد صلى الله عليه وسلم. فأقسم تعالى بهذه المواضع المقدسة، التي اختارها وابتعث منها أفضل النبوات وأشرفها.","4":"والمقسم عليه قوله: { لَقَدْ خَلَقْنَا الْإِنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ } أي: تام الخلق، متناسب الأعضاء، منتصب القامة، لم يفقد مما يحتاج إليه ظاهرًا أو باطنًا شيئًا، ومع هذه النعم العظيمة، التي ينبغي منه القيام بشكرها، فأكثر الخلق منحرفون عن شكر المنعم، مشتغلون باللهو واللعب، قد رضوا لأنفسهم بأسافل الأمور، وسفساف الأخلاق.","5":"فردهم الله في أسفل سافلين، أي: أسفل النار، موضع العصاة المتمردين على ربهم.","6":"إلا من من الله عليه بالإيمان والعمل الصالح، والأخلاق الفاضلة العالية، { فَلَهُمْ } بذلك المنازل العالية، و { أَجْرٌ غَيْرُ مَمْنُونٍ } أي: غير مقطوع، بل لذات متوافرة، وأفراح متواترة، ونعم متكاثرة، في أبد لا يزول، ونعيم لا يحول، أكلها دائم وظلها.","7":"{ فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ } أي: أي: شيء يكذبك أيها الإنسان بيوم الجزاء على الأعمال، وقد رأيت من آيات الله الكثيرة ما به يحصل لك اليقين، ومن نعمه ما يوجب عليك أن لا تكفر بشيء مما أخبرك به.","8":"{ أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ } فهل تقتضي حكمته أن يترك الخلق سدى لا يؤمرون ولا ينهون، ولا يثابون ولا يعاقبون؟أم الذي خلق الإنسان أطوارًا بعد أطوار، وأوصل إليهم من النعم والخير والبر ما لا يحصونه، ورباهم التربية الحسنة، لا بد أن يعيدهم إلى دار هي مستقرهم وغايتهم، التي إليها يقصدون، ونحوها يؤمون. تمت ولله الحمد."},"96":{"1":"هذه السورة أول السور القرآنية نزولًا على رسول الله صلى الله عليه وسلم.فإنها نزلت عليه في مبادئ النبوة، إذ كان لا يدري ما الكتاب ولا الإيمان، فجاءه جبريل عليه الصلاة والسلام بالرسالة، وأمره أن يقرأ، فامتنع، وقال: { ما أنا بقارئ } فلم يزل به حتى قرأ. فأنزل الله عليه: { اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ } عموم الخلق، ثم خص الإنسان.","2":"وذكر ابتداء خلقه { مِنْ عَلَقٍ } فالذي خلق الإنسان واعتنى بتدبيره، لا بد أن يدبره بالأمر والنهي، وذلك بإرسال الرسول إليهم ، وإنزال الكتب عليهم، ولهذا ذكر بعد الأمر بالقراءة، خلقه للإنسان.","3":"{ اقْرَأْ وَرَبُّكَ الْأَكْرَمُ } أي: كثير الصفات واسعها، كثير الكرم والإحسان، واسع الجود.","4":"الذي من كرمه أن علم بالعلم و { عَلَّمَ بِالْقَلَمِ}","5":"[عَلَّمَ الْإِنْسَانَ مَا لَمْ يَعْلَمْ } فإنه تعالى أخرجه من بطن أمه لا يعلم شيئًا، وجعل له السمع والبصر والفؤاد، ويسر له أسباب العلم.فعلمه القرآن، وعلمه الحكمة، وعلمه بالقلم، الذي به تحفظ به العلوم، وتضبط الحقوق، وتكون رسلًا للناس تنوب مناب خطابهم، فلله الحمد والمنة، الذي أنعم على عباده بهذه النعم التي لا يقدرون لها على جزاء ولا شكور، ثم من عليهم بالغنى وسعة الرزق.","6":"والإنسان -لجهله وظلمه- إذا رأى نفسه غنيًا، طغى وبغى وتجبر عن الهدى","7":6,"8":"ونسي أن إلى ربه الرجعى، ولم يخف الجزاء، بل ربما وصلت به الحال أنه يترك الهدى بنفسه، ويدعو [غيره] إلى تركه، فينهى عن الصلاة التي هي أفضل أعمال الإيمان.","9":"يقول الله لهذا المتمرد العاتي: { أَرَأَيْتَ } أيها الناهي للعبد إذا صلى","10":9,"11":"{ إِنْ كَانَ } العبد المصلي { عَلَى الْهُدَى } العلم بالحق والعمل به،","12":"{ أَوْ أَمْرٍ } غيره { بِالتَّقْوَى } .فهل يحسن أن ينهى، من هذا وصفه؟ أليس نهيه، من أعظم المحادة لله، والمحاربة للحق؟ فإن النهي، لا يتوجه إلا لمن هو في نفسه على غير الهدى، أو كان يأمر غيره بخلاف التقوى.","13":"{ أَرَأَيْتَ إِنْ كَذَّبَ } الناهي بالحق { وَتَوَلَّى } عن الأمر، أما يخاف الله ويخشى عقابه؟","14":"{ أَلَمْ يَعْلَمْ بِأَنَّ اللَّهَ يَرَى } ما يعمل ويفعل؟.","15":"ثم توعده إن استمر على حاله، فقال: { كَلَّا لَئِنْ لَمْ يَنْتَهِ } عما يقول ويفعل { لَنَسْفَعَنْ بِالنَّاصِيَةِ } أي: لنأخذن بناصيته، أخذًا عنيفًا، وهي حقيقة بذلك.","16":"فإنها { نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ } أي: كاذبة في قولها، خاطئة في فعلها.","17":"{ فَلْيَدْعُ } هذا الذي حق عليه العقاب { نَادِيَهُ } أي: أهل مجلسه وأصحابه ومن حوله، ليعينوه على ما نزله به.","18":"{ سَنَدْعُ الزَّبَانِيَةَ } أي: خزنة جهنم، لأخذه وعقوبته، فلينظر أي: الفريقين أقوى وأقدر؟ فهذه حالة الناهي وما توعد به من العقوبة.","19":"وأما حالة المنهي، فأمره الله أن لا يصغى إلى هذا الناهي ولا ينقاد لنهيه فقال: { كَلَّا لَا تُطِعْهُ } [أي:] فإنه لا يأمر إلا بما فيه خسارة الدارين، { وَاسْجُدْ } لربك { وَاقْتَرَبَ } منه في السجود وغيره من أنواع الطاعات والقربات، فإنها كلها تدني من رضاه وتقرب منه.وهذا عام لكل ناه عن الخير ومنهي عنه، وإن كانت نازلة في شأن أبي جهل حين نهى رسول الله صلى الله عليه وسلم عن الصلاة، وعبث به وآذاه. تمت ولله الحمد."},"97":{"1":"يقول تعالى مبينًا لفضل القرآن وعلو قدره: { إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ } كما قال تعالى: { إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةٍ مُبَارَكَةٍ } وذلك أن الله [تعالى] ، ابتدأ بإنزاله في رمضان [في] ليلة القدر، ورحم الله بها العباد رحمة عامة، لا يقدر العباد لها شكرًا.وسميت ليلة القدر، لعظم قدرها وفضلها عند الله، ولأنه يقدر فيها ما يكون في العام من الأجل والأرزاق والمقادير القدرية.","2":"ثم فخم شأنها، وعظم مقدارها فقال: { وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ } أي: فإن شأنها جليل، وخطرها عظيم.","3":"{ لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ } أي: تعادل من فضلها ألف شهر، فالعمل الذي يقع فيها، خير من العمل في ألف شهر [خالية منها]، وهذا مما تتحير فيه الألباب، وتندهش له العقول، حيث من تبارك وتعالى على هذه الأمة الضعيفة القوة والقوى، بليلة يكون العمل فيها يقابل ويزيد على ألف شهر، عمر رجل معمر عمرًا طويلًا، نيفًا وثمانين سنة.","4":"{ تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا } أي: يكثر نزولهم فيها { مِنْ كُلِّ أَمْر}","5":"[ سَلَامٌ هِيَ } أي: سالمة من كل آفة وشر، وذلك لكثرة خيرها، { حَتَّى مَطْلَعِ الْفَجْرِ } أي: مبتداها من غروب الشمس ومنتهاها طلوع الفجر .وقد تواترت الأحاديث في فضلها، وأنها في رمضان، وفي العشر الأواخر منه، خصوصًا في أوتاره، وهي باقية في كل سنة إلى قيام الساعة.ولهذا كان النبي صلى الله عليه وسلم، يعتكف، ويكثر من التعبد في العشر الأواخر من رمضان، رجاء ليلة القدر [والله أعلم]."},"98":{"1":"يقول تعالى: { لَمْ يَكُنِ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ } أي: [من] اليهود والنصارى { وَالْمُشْرِكِينَ } من سائر أصناف الأمم.{ مُنْفَكِّينَ } عن كفرهم وضلالهم الذي هم عليه، أي: لا يزالون في غيهم وضلالهم، لا يزيدهم مرور السنين إلا كفرًا.{ حَتَّى تَأْتِيَهُمُ الْبَيِّنَةُ } الواضحة، والبرهان الساطع.","2":"ثم فسر تلك البينة فقال: { رَسُولٌ مِنَ اللَّهِ } أي: أرسله الله، يدعو الناس إلى الحق، وأنزل عليه كتابًا يتلوه، ليعلم الناس الحكمة ويزكيهم، ويخرجهم من الظلمات إلى النور{ يَتْلُو صُحُفًا مُطَهَّرَةً } أي: محفوظة عن قربان الشياطين، لا يمسها إلا المطهرون، لأنها في أعلى ما يكون من الكلام.","3":"{ فِيهَا } أي: في تلك الصحف { كُتُبٌ قَيِّمَةٌ } أي: أخبار صادقة، وأوامر عادلة تهدي إلى الحق وإلى صراط مستقيم، فإذا جاءتهم هذه البينة، فحينئذ يتبين طالب الحق ممن ليس له مقصد في طلبه، فيهلك من هلك عن بينة، ويحيا من حي عن بينة.","4":"وإذا لم يؤمن أهل الكتاب لهذا الرسول وينقادوا له، فليس ذلك ببدع من ضلالهم وعنادهم، فإنهم ما تفرقوا واختلفوا وصاروا أحزابًا { إِلَّا مِنْ بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَةُ } التي توجب لأهلها الاجتماع والاتفاق، ولكنهم لرداءتهم ونذالتهم، لم يزدهم الهدى إلا ضلالًا، ولا البصيرة إلا عمى، مع أن الكتب كلها جاءت بأصل واحد، ودين واحد.","5":"فما أمروا في سائر الشرائع إلا أن يعبدوا { اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ } أي: قاصدين بجميع عباداتهم الظاهرة والباطنة وجه الله، وطلب الزلفى لديه، { حُنَفَاءَ } أي: معرضين [مائلين] عن سائر الأديان المخالفة لدين التوحيد. وخص الصلاة والزكاة [بالذكر] مع أنهما داخلان في قوله { لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ } لفضلهما وشرفهما، وكونهما العبادتين اللتين من قام بهما قام بجميع شرائع الدين.{ وَذَلِكَ } أي التوحيد والإخلاص في الدين، هو { دِينُ الْقَيِّمَةِ } أي: الدين المستقيم، الموصل إلى جنات النعيم، وما سواه فطرق موصلة إلى الجحيم.","6":"ثم ذكر جزاء الكافرين بعدما جاءتهم البينة، فقال: { إِنَّ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ فِي نَارِ جَهَنَّمَ } قد أحاط بهم عذابها، واشتد عليهم عقابها، { خَالِدِينَ فِيهَا } لا يفتر عنهم العذاب، وهم فيها مبلسون، { أُولَئِكَ هُمْ شَرُّ الْبَرِيَّةِ } لأنهم عرفوا الحق وتركوه، وخسروا الدنيا والآخرة.","7":"{ إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَئِكَ هُمْ خَيْرُ الْبَرِيَّةِ } لأنهم عبدوا الله وعرفوه، وفازوا بنعيم الدنيا والآخرة.","8":"{ جَزَاؤُهُمْ عِنْدَ رَبِّهِمْ جَنَّاتُ عَدْنٍ } أي: جنات إقامة، لا ظعن فيها ولا رحيل، ولا طلب لغاية فوقها، { تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ } فرضي عنهم بما قاموا به من مراضيه، ورضوا عنه، بما أعد لهم من أنواع الكرامات وجزيل المثوبات { ذَلِكَ } الجزاء الحسن { لِمَنْ خَشِيَ رَبَّهُ } أي: لمن خاف الله، فأحجم عن معاصيه، وقام بواجباته [تمت بحمد لله]"},"99":{"1":"يخبر تعالى عما يكون يوم القيامة، وأن الأرض تتزلزل وترجف وترتج، حتى يسقط ما عليها من بناء وعلم .فتندك جبالها، وتسوى تلالها، وتكون قاعًا صفصفًا لا عوج فيه ولا أمت.","2":"{ وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا } أي: ما في بطنها، من الأموات والكنوز.","3":"{ وَقَالَ الْإِنْسَانُ } إذا رأى ما عراها من الأمر العظيم مستعظمًا لذلك: { مَا لَهَا } ؟ أي: أي شيء عرض لها؟.","4":"{ يَوْمَئِذٍ تُحَدِّثُ } الأرض { أَخْبَارَهَا } أي: تشهد على العاملين بما عملوا على ظهرها من خير وشر، فإن الأرض من جملة الشهود الذين يشهدون على العباد بأعمالهم.","5":"ذلك { بِأَنَّ رَبَّكَ أَوْحَى لَهَا } أي وأمرها أن تخبر بما عمل عليها، فلا تعصى لأمره .","6":"{ يَوْمَئِذٍ يَصْدُرُ النَّاسُ } من موقف القيامة، حين يقضي الله بينهم { أَشْتَاتًا } أي: فرقًا متفاوتين. { لِيُرَوْا أَعْمَالَهُمْ } أي: ليريهم الله ما عملوا من الحسنات والسيئات، ويريهم جزاءه موفرًا.","7":"{ فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ } وهذا شامل عام للخير والشر كله، لأنه إذا رأى مثقال الذرة، التي هي أحقر الأشياء، [وجوزي عليها] فما فوق ذلك من باب أولى وأحرى، كما قال تعالى: { يَوْمَ تَجِدُ كُلُّ نَفْسٍ مَا عَمِلَتْ مِنْ خَيْرٍ مُحْضَرًا وَمَا عَمِلَتْ مِنْ سُوءٍ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُ أَمَدًا بَعِيدًا } { وَوَجَدُوا مَا عَمِلُوا حَاضِرًا } وهذه الآية فيها غاية الترغيب في فعل الخير ولو قليلًا، والترهيب من فعل الشر ولو حقيرًا.","8":7},"100":{"1":"أقسم الله تبارك وتعالى بالخيل، لما فيها من آيات الله الباهرة، ونعمه الظاهرة، ما هو معلوم للخلق. وأقسم [تعالى] بها في الحال التي لا يشاركها [فيه] غيرها من أنواع الحيوانات، فقال: { وَالْعَادِيَاتِ ضَبْحًا } أي: العاديات عدوًا بليغًا قويًا، يصدر عنه الضبح، وهو صوت نفسها في صدرها، عند اشتداد العدو .","2":"{ فَالْمُورِيَاتِ } بحوافرهن ما يطأن عليه من الأحجار { قَدْحًا } أي: تقدح النار من صلابة حوافرهن [وقوتهن] إذا عدون،","3":"{ فَالْمُغِيرَاتِ } على الأعداء { صُبْحًا } وهذا أمر أغلبي، أن الغارة تكون صباحًا.","4":"{ فَأَثَرْنَ بِهِ } أي: بعدوهن وغارتهن { نَقْعًا } أي: غبارًا.","5":"{ فَوَسَطْنَ بِهِ } أي: براكبهن { جَمْعًا } أي: توسطن به جموع الأعداء، الذين أغار عليهم.","6":"والمقسم عليه، قوله: { إِنَّ الْإِنْسَانَ لِرَبِّهِ لَكَنُودٌ } أي: لمنوع للخير الذي عليه لربه . فطبيعة [الإنسان] وجبلته، أن نفسه لا تسمح بما عليه من الحقوق، فتؤديها كاملة موفرة، بل طبيعتها الكسل والمنع لما عليه من الحقوق المالية والبدنية، إلا من هداه الله وخرج عن هذا الوصف إلى وصف السماح بأداء الحقوق.","7":"{ وَإِنَّهُ عَلَى ذَلِكَ لَشَهِيدٌ } أي: إن الإنسان على ما يعرف من نفسه من المنع والكند لشاهد بذلك، لا يجحده ولا ينكره، لأن ذلك أمر بين واضح. ويحتمل أن الضمير عائد إلى الله تعالى أي: إن العبد لربه لكنود، والله شهيد على ذلك، ففيه الوعيد، والتهديد الشديد، لمن هو لربه كنود، بأن الله عليه شهيد.","8":"{ وَإِنَّهُ } أي: الإنسان { لِحُبِّ الْخَيْرِ } أي: المال { لَشَدِيدُ } أي: كثير الحب للمال. وحبه لذلك، هو الذي أوجب له ترك الحقوق الواجبة عليه، قدم شهوة نفسه على حق ربه، وكل هذا لأنه قصر نظره على هذه الدار، وغفل عن الآخرة، ولهذا قال حاثًا له على خوف يوم الوعيد:","9":"{ أَفَلَا يَعْلَمُ } أي: هلا يعلم هذا المغتر { إِذَا بُعْثِرَ مَا فِي الْقُبُورِ } أي: أخرج الله الأموات من قبورهم، لحشرهم ونشورهم.","10":"{ وَحُصِّلَ مَا فِي الصُّدُورِ } أي: ظهر وبان [ما فيها و] ما استتر في الصدور من كمائن الخير والشر، فصار السر علانية، والباطن ظاهرًا، وبان على وجوه الخلق نتيجة أعمالهم.","11":"{ إِنَّ رَبَّهُمْ بِهِمْ يَوْمَئِذٍ لَخَبِيرٌ } أي مطلع على أعمالهم الظاهرة والباطنة، الخفية والجلية، ومجازيهم عليها. وخص خبره بذلك اليوم، مع أنه خبير بهم في كل وقت، لأن المراد بذلك، الجزاء بالأعمال الناشئ عن علم الله واطلاعه."},"101":{"1":"{ الْقَارِعَةُ } من أسماء يوم القيامة، سميت بذلك، لأنها تقرع الناس وتزعجهم بأهوالها، ولهذا عظم أمرها وفخمه .","2":"عظَّم أمرها وفخمه","3":2,"4":"{ يَوْمَ يَكُونُ النَّاسُ } من شدة الفزع والهول، { كَالْفَرَاشِ الْمَبْثُوث } أي: كالجراد المنتشر، الذي يموج بعضه في بعض، والفراش: هي الحيوانات التي تكون في الليل، يموج بعضها ببعض لا تدري أين توجه، فإذا أوقد لها نار تهافتت إليها لضعف إدراكها، فهذه حال الناس أهل العقول،","5":"وأما الجبال الصم الصلاب، فتكون { كَالْعِهْنِ الْمَنْفُوشِ } أي: كالصوف المنفوش، الذي بقي ضعيفًا جدًا، تطير به أدنى ريح، قال تعالى: { وَتَرَى الْجِبَالَ تَحْسَبُهَا جَامِدَةً وَهِيَ تَمُرُّ مَرَّ السَّحَابِ } ثم بعد ذلك، تكون هباء منثورًا، فتضمحل ولا يبقى منها شيء يشاهد، فحينئذ تنصب الموازين، وينقسم الناس قسمين: سعداء وأشقياء،","6":"{ فَأَمَّا مَنْ ثَقُلَتْ مَوَازِينُهُ } أي: رجحت حسناته على سيئاته","7":"{ فَهُوَ فِي عِيشَةٍ رَاضِيَةٍ } في جنات النعيم.","8":"{ وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ } بأن لم تكن له حسنات تقاوم سيئاته.","9":"{ فَأُمُّهُ هَاوِيَةٌ } أي: مأواه ومسكنه النار، التي من أسمائها الهاوية، تكون له بمنزلة الأم الملازمة كما قال تعالى: { إِنَّ عَذَابَهَا كَانَ غَرَامًا } .وقيل: إن معنى ذلك، فأم دماغه هاوية في النار، أي: يلقى في النار على رأسه.","10":"{ وَمَا أَدْرَاكَ مَاهِيَهْ } وهذا تعظيم لأمرها،","11":"{ نَارٌ حَامِيَةٌ } أي: شديدة الحرارة، قد زادت حرارتها على حرارة نار الدنيا سبعين ضعفًا. نستجير بالله منها."},"102":{"1":"يقول تعالى موبخًا عباده عن اشتغالهم عما خلقوا له من عبادته وحده لا شريك له، ومعرفته، والإنابة إليه، وتقديم محبته على كل شيء: { أَلْهَاكُمُ } عن ذلك المذكور { التَّكَاثُرُ } ولم يذكر المتكاثر به، ليشمل ذلك كل ما يتكاثر به المتكاثرون، ويفتخر به المفتخرون، من التكاثر في الأموال، والأولاد، والأنصار، والجنود، والخدم، والجاه، وغير ذلك مما يقصد منه مكاثرة كل واحد للآخر، وليس المقصود به الإخلاص لله تعالى.","2":"فاستمرت غفلتكم ولهوتكم [وتشاغلكم] { حَتَّى زُرْتُمُ الْمَقَابِرَ } فانكشف لكم حينئذ الغطاء، ولكن بعد ما تعذر عليكم استئنافه.ودل قوله: { حَتَّى زُرْتُمُ الْمَقَابِرَ } أن البرزخ دار مقصود منها النفوذ إلى الدار الباقية ، أن الله سماهم زائرين، ولم يسمهم مقيمين.","3":"{ كَلَّا سَوْفَ تَعْلَمُونَ ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ كَلَّا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ } أي: لو تعلمون ما أمامكم علمًا يصل إلى القلوب، لما ألهاكم التكاثر، ولبادرتم إلى الأعمال الصالحة.","4":3,"5":3,"6":"ولكن عدم العلم الحقيقي، صيركم إلى ما ترون، { لَتَرَوُنَّ الْجَحِيمَ } أي: لتردن القيامة، فلترون الجحيم التي أعدها الله للكافرين.","7":"{ ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ } أي: رؤية بصرية، كما قال تعالى: { وَرَأَى الْمُجْرِمُونَ النَّارَ فَظَنُّوا أَنَّهُمْ مُوَاقِعُوهَا وَلَمْ يَجِدُوا عَنْهَا مَصْرِفًا } .","8":"{ ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ } الذي تنعمتم به في دار الدنيا، هل قمتم بشكره، وأديتم حق الله فيه، ولم تستعينوا به، على معاصيه، فينعمكم نعيمًا أعلى منه وأفضل.أم اغتررتم به، ولم تقوموا بشكره؟ بل ربما استعنتم به على معاصي الله فيعاقبكم على ذلك، قال تعالى: { وَيَوْمَ يُعْرَضُ الَّذِينَ كَفَرُوا عَلَى النَّارِ أَذْهَبْتُمْ طَيِّبَاتِكُمْ فِي حَيَاتِكُمُ الدُّنْيَا وَاسْتَمْتَعْتُمْ بِهَا فَالْيَوْمَ تُجْزَوْنَ عَذَابَ الْهُونِ } الآية."},"103":{"1":"أقسم تعالى بالعصر، الذي هو الليل والنهار، محل أفعال العباد وأعمالهم","2":"أن كل إنسان خاسر، والخاسر ضد الرابح.والخسار مراتب متعددة متفاوتة:قد يكون خسارًا مطلقًا، كحال من خسر الدنيا والآخرة، وفاته النعيم، واستحق الجحيم.","3":"وقد يكون خاسرًا من بعض الوجوه دون بعض، ولهذا عمم الله الخسار لكل إنسان، إلا من اتصف بأربع صفات:الإيمان بما أمر الله بالإيمان به، ولا يكون الإيمان بدون العلم، فهو فرع عنه لا يتم إلا به.والعمل الصالح، وهذا شامل لأفعال الخير كلها، الظاهرة والباطنة، المتعلقة بحق الله وحق عباده ، الواجبة والمستحبة.والتواصي بالحق، الذي هو الإيمان والعمل الصالح، أي: يوصي بعضهم بعضًا بذلك، ويحثه عليه، ويرغبه فيه.والتواصي بالصبر على طاعة الله، وعن معصية الله، وعلى أقدار الله المؤلمة.فبالأمرين الأولين، يكمل الإنسان نفسه، وبالأمرين الأخيرين يكمل غيره، وبتكميل الأمور الأربعة، يكون الإنسان قد سلم من الخسار، وفاز بالربح [العظيم]."},"104":{"1":"{ وَيْلٌ } أي: وعيد، ووبال، وشدة عذاب { لِكُلِّ هُمَزَةٍ لُمَزَةٍ } الذي يهمز الناس بفعله، ويلمزهم بقوله، فالهماز: الذي يعيب الناس، ويطعن عليهم بالإشارة والفعل، واللماز: الذي يعيبهم بقوله.","2":"ومن صفة هذا الهماز اللماز، أنه لا هم له سوى جمع المال وتعديده والغبطة به، وليس له رغبة في إنفاقه في طرق الخيرات وصلة الأرحام، ونحو ذلك،","3":"{ يَحْسَبُ } بجهله { أَنَّ مَالَهُ أَخْلَدَهُ } في الدنيا، فلذلك كان كده وسعيه كله في تنمية ماله، الذي يظن أنه ينمي عمره، ولم يدر أن البخل يقصف الأعمار، ويخرب الديار، وأن البر يزيد في العمر.","4":"{ كَلَّا لَيُنْبَذَنَّ } أي: ليطرحن { فِي الْحُطَمَةِ}","5":"[وَمَا أَدْرَاكَ مَا الْحُطَمَةُ } تعظيم لها، وتهويل لشأنها.","6":"{ نَارُ اللَّهِ الْمُوقَدَةُ } التي وقودها الناس والحجارة","7":"{ الَّتِي } من شدتها { تَطَّلِعُ عَلَى الْأَفْئِدَةِ } أي: تنفذ من الأجسام إلى القلوب.","8":"ومع هذه الحرارة البليغة هم محبوسون فيها، قد أيسوا من الخروج منها، ولهذا قال: { إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ } أي: مغلقة","9":"{ فِي عَمَدٍ } من خلف الأبواب { مُمَدَّدَةٍ } لئلا يخرجوا منها { كُلَّمَا أَرَادُوا أَنْ يَخْرُجُوا مِنْهَا أُعِيدُوا فِيهَا } .[نعوذ بالله من ذلك، ونسأله العفو والعافية]."},"105":{"1":"أي: أما رأيت من قدرة الله وعظيم شأنه، ورحمته بعباده، وأدلة توحيده، وصدق رسوله محمد صلى الله عليه وسلم، ما فعله الله بأصحاب الفيل، الذين كادوا بيته الحرام وأرادوا إخرابه، فتجهزوا لأجل ذلك، واستصحبوا معهم الفيلة لهدمه، وجاءوا بجمع لا قبل للعرب به، من الحبشة واليمن، فلما انتهوا إلى قرب مكة، ولم يكن بالعرب مدافعة، وخرج أهل مكة من مكة خوفًا على أنفسهم منهم.","2":"كفى الله شرهم، ورد كيدهم في نحورهم","3":"أرسل الله عليهم طيرًا أبابيل أي: متفرقة.","4":"تحمل حجارة محماة من سجيل، فرمتهم بها، وتتبعت قاصيهم ودانيهم، فخمدوا وهمدوا.","5":"وصاروا كعصف مأكول، وكفى الله شرهم، ورد كيدهم في نحورهم، [وقصتهم معروفة مشهورة] وكانت تلك السنة التي ولد فيها رسول الله صلى الله عليه وسلم، فصارت من جملة إرهاصات دعوته، ومقدمات رسالته، فلله الحمد والشكر."},"106":{"1":"قال كثير من المفسرين: إن الجار والمجرور متعلق بالسورة التي قبلها أي: فعلنا ما فعلنا بأصحاب الفيل لأجل قريش وأمنهم، واستقامة مصالحهم، وانتظام رحلتهم في الشتاء لليمن، والصيف للشام، لأجل التجارة والمكاسب.","2":1,"3":"فأهلك الله من أرادهم بسوء، وعظم أمر الحرم وأهله في قلوب العرب، حتى احترموهم، ولم يعترضوا لهم في أي: سفر أرادوا، ولهذا أمرهم الله بالشكر، فقال: { فَلْيَعْبُدُوا رَبَّ هَذَا الْبَيْتِ } أي: ليوحدوه ويخلصوا له العبادة.","4":"{ الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ وَآمَنَهُمْ مِنْ خَوْفٍ } فرغد الرزق والأمن من المخاوف، من أكبر النعم الدنيوية، الموجبة لشكر الله تعالى.فلك اللهم الحمد والشكر على نعمك الظاهرة والباطنة، وخص الله بالربوبية البيت لفضله وشرفه، وإلا فهو رب كل شيء.."},"107":{"1":"يقول تعالى ذامًا لمن ترك حقوقه وحقوق عبادة: { أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ } أي: بالبعث والجزاء، فلا يؤمن بما جاءت به الرسل.","2":"{ فَذَلِكَ الَّذِي يَدُعُّ الْيَتِيمَ } أي: يدفعه بعنف وشدة، ولا يرحمه لقساوة قلبه، ولأنه لا يرجو ثوابًا، ولا يخشى عقابًا.","3":"{ وَلَا يَحُضُّ } غيره { عَلَى طَعَامِ الْمِسْكِينِ } ومن باب أولى أنه بنفسه لا يطعم المسكين.","4":"{ فَوَيْلٌ لِلْمُصَلِّينَ } أي: الملتزمون لإقامة الصلاة، ولكنهم { عَنْ صَلَاتِهِمْ سَاهُونَ }","5":"أي: مضيعون لها، تاركون لوقتها، مفوتون لأركانها وهذا لعدم اهتمامهم بأمر الله حيث ضيعوا الصلاة، التي هي أهم الطاعات وأفضل القربات، والسهو عن الصلاة، هو الذي يستحق صاحبه الذم واللوم وأما السهو في الصلاة، فهذا يقع من كل أحد، حتى من النبي صلى الله عليه وسلم.","6":"ولهذا وصف الله هؤلاء بالرياء والقسوة وعدم الرحمة، فقال: { الَّذِينَ هُمْ يُرَاءُونَ } أي يعملون الأعمال لأجل رئاء الناس.","7":"{ وَيَمْنَعُونَ الْمَاعُونَ } أي: يمنعون إعطاء الشيء، الذي لا يضر إعطاؤه على وجه العارية، أو الهبة، كالإناء، والدلو، والفأس، ونحو ذلك، مما جرت العادة ببذلها والسماحة به .فهؤلاء -لشدة حرصهم- يمنعون الماعون، فكيف بما هو أكثر منه.وفي هذه السورة، الحث على إكرام اليتيم، والمساكين، والتحضيض على ذلك، ومراعاة الصلاة، والمحافظة عليها، وعلى الإخلاص [فيها و] في جميع الأعمال.والحث على [فعل المعروف و] بذل الأموال الخفيفة، كعارية الإناء والدلو والكتاب، ونحو ذلك، لأن الله ذم من لم يفعل ذلك، والله سبحانه وتعالى أعلم بالصواب والحمد لله رب العالمين."},"108":{"1":"يقول الله تعالى لنبيه محمد صلى الله عليه وسلم ممتنا عليه: { إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ } أي: الخير الكثير، والفضل الغزير، الذي من جملته، ما يعطيه الله لنبيه صلى الله عليه وسلم يوم القيامة، من النهر الذي يقال له { الكوثر } ومن الحوض طوله شهر، وعرضه شهر، ماؤه أشد بياضًا من اللبن، وأحلى من العسل، آنيته كنجوم السماء في كثرتها واستنارتها، من شرب منه شربة لم يظمأ بعدها أبدًا.","2":"ولما ذكر منته عليه، أمره بشكرها فقال: { فَصَلِّ لِرَبِّكَ وَانْحَرْ } خص هاتين العبادتين بالذكر، لأنهما من أفضل العبادات وأجل القربات.ولأن الصلاة تتضمن الخضوع [في] القلب والجوارح لله، وتنقلها في أنواع العبودية، وفي النحر تقرب إلى الله بأفضل ما عند العبد من النحائر، وإخراج للمال الذي جبلت النفوس على محبته والشح به.","3":"{ إِنَّ شَانِئَكَ } أي: مبغضك وذامك ومنتقصك { هُوَ الْأَبْتَرُ } أي: المقطوع من كل خير، مقطوع العمل، مقطوع الذكر.وأما محمد صلى الله عليه وسلم، فهو الكامل حقًا، الذي له الكمال الممكن في حق المخلوق، من رفع الذكر، وكثرة الأنصار، والأتباع صلى الله عليه وسلم."},"109":{"1":"أي: قل للكافرين معلنا ومصرحًا","2":"{ لَا أَعْبُدُ مَا تَعْبُدُونَ } أي: تبرأ مما كانوا يعبدون من دون الله، ظاهرًا وباطنًا.","3":"{ وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ } لعدم إخلاصكم في عبادته ، فعبادتكم له المقترنة بالشرك لا تسمى عبادة، ثم كرر ذلك ليدل الأول على عدم وجود الفعل، والثاني على أن ذلك قد صار وصفًا لازمًا.","4":3,"5":"يدل على أن ذلك قد صار وصفاً لازماً.","6":"ولهذا ميز بين الفريقين، وفصل بين الطائفتين، فقال: { لَكُمْ دِينُكُمْ وَلِيَ دِينِ } كما قال تعالى: { قُلْ كُلٌّ يَعْمَلُ عَلَى شَاكِلَتِهِ } { أَنْتُمْ بَرِيئُونَ مِمَّا أَعْمَلُ وَأَنَا بَرِيءٌ مِمَّا تَعْمَلُونَ } ."},"110":{"1":"في هذه السورة الكريمة، بشارة وأمر لرسوله عند حصولها، وإشارة وتنبيه على ما يترتب على ذلك.فالبشارة هي البشارة بنصر الله لرسوله، وفتحه مكة.","2":"ودخول الناس في دين الله أفواجًا، بحيث يكون كثير منهم من أهله وأنصاره، بعد أن كانوا من أعدائه، وقد وقع هذا المبشر به،","3":"وأما الأمر بعد حصول النصر والفتح، فأمر رسوله أن يشكر ربه على ذلك، ويسبح بحمده ويستغفره، وأما الإشارة، فإن في ذلك إشارتين: إشارة لأن يستمر النصر لهذا الدين ، ويزداد عند حصول التسبيح بحمد الله واستغفاره من رسوله، فإن هذا من الشكر، والله يقول: { لَئِنْ شَكَرْتُمْ لَأَزِيدَنَّكُمْ } وقد وجد ذلك في زمن الخلفاء الراشدين وبعدهم في هذه الأمة لم يزل نصر الله مستمرًا، حتى وصل الإسلام إلى ما لم يصل إليه دين من الأديان، ودخل فيه، ما لم يدخل في غيره، حتى حدث من الأمة من مخالفة أمر الله ما حدث، فابتلاهم الله بتفرق الكلمة، وتشتت الأمر، فحصل ما حصل.[ومع هذا] فلهذه الأمة، وهذا الدين، من رحمة الله ولطفه، ما لا يخطر بالبال، أو يدور في الخيال.وأما الإشارة الثانية، فهي الإشارة إلى أن أجل رسول الله صلى الله عليه وسلم قد قرب ودنا، ووجه ذلك أن عمره عمر فاضل أقسم الله به.وقد عهد أن الأمور الفاضلة تختم بالاستغفار، كالصلاة والحج، وغير ذلك.فأمر الله لرسوله بالحمد والاستغفار في هذه الحال، إشارة إلى أن أجله قد انتهى، فليستعد ويتهيأ للقاء ربه، ويختم عمره بأفضل ما يجده صلوات الله وسلامه عليه.فكان صلى الله عليه وسلم يتأول القرآن، ويقول ذلك في صلاته، يكثر أن يقول في ركوعه وسجوده: \\\" سبحانك اللهم وبحمدك، اللهم اغفر لي \\\"."},"111":{"1":"أبو لهب هو عم النبي صلى الله عليه وسلم، وكان شديد العداوة [والأذية] للنبي صلى الله عليه وسلم، فلا فيه دين، ولا حمية للقرابة -قبحه الله- فذمه الله بهذا الذم العظيم، الذي هو خزي عليه إلى يوم القيامة فقال: { تَبَّتْ يَدَا أَبِي لَهَبٍ } أي: خسرت يداه، وشقى { وَتَبَّ } فلم يربح،","2":"{ مَا أَغْنَى عَنْهُ مَالُهُ } الذي كان عنده وأطغاه، ولا ما كسبه فلم يرد عنه شيئًا من عذاب الله إذ نزل به،","3":"{ سَيَصْلَى نَارًا ذَاتَ لَهَبٍ } أي: ستحيط به النار من كل جانب،","4":"هو { وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ } .وكانت أيضًا شديدة الأذية لرسول الله صلى الله عليه وسلم، تتعاون هي وزوجها على الإثم والعدوان، وتلقي الشر، وتسعى غاية ما تقدر عليه في أذية الرسول صلى الله عليه وسلم،","5":"وتجمع على ظهرها من الأوزار بمنزلة من يجمع حطبًا، قد أعد له في عنقه حبلًا { مِنْ مَسَدٍ } أي: من ليف.أو أنها تحمل في النار الحطب على زوجها، متقلدة في عنقها حبلًا من مسد، وعلى كل، ففي هذه السورة، آية باهرة من آيات الله، فإن الله أنزل هذه السورة، وأبو لهب وامرأته لم يهلكا، وأخبر أنهما سيعذبان في النار ولا بد، ومن لازم ذلك أنهما لا يسلمان، فوقع كما أخبر عالم الغيب والشهادة."},"112":{"1":"أي { قُلْ } قولًا جازمًا به، معتقدًا له، عارفًا بمعناه، { هُوَ اللَّهُ أَحَدٌ } أي: قد انحصرت فيه الأحدية، فهو الأحد المنفرد بالكمال، الذي له الأسماء الحسنى، والصفات الكاملة العليا، والأفعال المقدسة، الذي لا نظير له ولا مثيل.","2":"{ اللَّهُ الصَّمَدُ } أي: المقصود في جميع الحوائج. فأهل العالم العلوي والسفلي مفتقرون إليه غاية الافتقار، يسألونه حوائجهم، ويرغبون إليه في مهماتهم، لأنه الكامل في أوصافه، العليم الذي قد كمل في علمه، الحليم الذي قد كمل في حلمه، الرحيم الذي [كمل في رحمته الذي] وسعت رحمته كل شيء، وهكذا سائر أوصافه،","3":"ومن كماله أنه { لَمْ يَلِدْ وَلَمْ يُولَدْ } لكمال غناه","4":"{ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ } لا في أسمائه ولا في أوصافه، ولا في أفعاله، تبارك وتعالى.فهذه السورة مشتملة على توحيد الأسماء والصفات."},"113":{"1":"أي: { قل } متعوذًا { أَعُوذُ } أي: ألجأ وألوذ، وأعتصم { بِرَبِّ الْفَلَقِ } أي: فالق الحب والنوى، وفالق الإصباح.","2":"{ مِنْ شَرِّ مَا خَلَقَ } وهذا يشمل جميع ما خلق الله، من إنس، وجن، وحيوانات، فيستعاذ بخالقها، من الشر الذي فيها،","3":"ثم خص بعد ما عم، فقال: { وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ } أي: من شر ما يكون في الليل، حين يغشى الناس، وتنتشر فيه كثير من الأرواح الشريرة، والحيوانات المؤذية.","4":"{ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ } أي: ومن شر السواحر، اللاتي يستعن على سحرهن بالنفث في العقد، التي يعقدنها على السحر.","5":"{ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ } والحاسد، هو الذي يحب زوال النعمة عن المحسود فيسعى في زوالها بما يقدر عليه من الأسباب، فاحتيج إلى الاستعاذة بالله من شره، وإبطال كيده، ويدخل في الحاسد العاين، لأنه لا تصدر العين إلا من حاسد شرير الطبع، خبيث النفس، فهذه السورة، تضمنت الاستعاذة من جميع أنواع الشرور، عمومًا وخصوصًا.ودلت على أن السحر له حقيقة يخشى من ضرره، ويستعاذ بالله منه [ومن أهله]."},"114":{"1":"وهذه السورة مشتملة على الاستعاذة برب الناس ومالكهم وإلههم، من الشيطان الذي هو أصل الشرور كلها ومادتها، الذي من فتنته وشره، أنه يوسوس في صدور الناس، فيحسن لهم الشر، ويريهم إياه في صورة حسنة، وينشط إرادتهم لفعله، ويقبح لهم الخير ويثبطهم عنه، ويريهم إياه في صورة غير صورته، وهو دائمًا بهذه الحال يوسوس ويخنس أي: يتأخر إذا ذكر العبد ربه واستعان على دفعه.فينبغي له أن [يستعين و] يستعيذ ويعتصم بربوبية الله للناس كلهم.وأن الخلق كلهم، داخلون تحت الربوبية والملك، فكل دابة هو آخذ بناصيتها.وبألوهيته التي خلقهم لأجلها، فلا تتم لهم إلا بدفع شر عدوهم، الذي يريد أن يقتطعهم عنها ويحول بينهم وبينها، ويريد أن يجعلهم من حزبه ليكونوا من أصحاب السعير، والوسواس كما يكون من الجن يكون من الإنس، ولهذا قال: { مِنَ الْجِنَّةِ وَالنَّاسِ } .","2":"وهذه السورة مشتملة على الاستعاذة برب الناس ومالكهم وإلههم، من الشيطان الذي هو أصل الشرور كلها ومادتها، الذي من فتنته وشره، أنه يوسوس في صدور الناس، فيحسن لهم الشر، ويريهم إياه في صورة حسنة، وينشط إرادتهم لفعله، ويقبح لهم الخير ويثبطهم عنه، ويريهم إياه في صورة غير صورته، وهو دائمًا بهذه الحال يوسوس ويخنس أي: يتأخر إذا ذكر العبد ربه واستعان على دفعه.فينبغي له أن يستعين و يستعيذ ويعتصم بربوبية الله للناس كلهم.وأن الخلق كلهم، داخلون تحت الربوبية والملك، فكل دابة هو آخذ بناصيتها.وبألوهيته التي خلقهم لأجلها، فلا تتم لهم إلا بدفع شر عدوهم، الذي يريد أن يقتطعهم عنها ويحول بينهم وبينها، ويريد أن يجعلهم من حزبه ليكونوا من أصحاب السعير، والوسواس كما يكون من الجن يكون من الإنس، ولهذا قال: { مِنَ الْجِنَّةِ وَالنَّاسِ } .","3":2,"4":2,"5":2,"6":"وهذه السورة مشتملة على الاستعاذة برب الناس ومالكهم وإلههم، من الشيطان الذي هو أصل الشرور كلها ومادتها، الذي من فتنته وشره، أنه يوسوس في صدور الناس، فيحسن لهم الشر، ويريهم إياه في صورة حسنة، وينشط إرادتهم لفعله، ويقبح لهم الخير ويثبطهم عنه، ويريهم إياه في صورة غير صورته، وهو دائمًا بهذه الحال يوسوس ويخنس أي: يتأخر إذا ذكر العبد ربه واستعان على دفعه.فينبغي له أن يستعين و يستعيذ ويعتصم بربوبية الله للناس كلهم.وأن الخلق كلهم، داخلون تحت الربوبية والملك، فكل دابة هو آخذ بناصيتها.وبألوهيته التي خلقهم لأجلها، فلا تتم لهم إلا بدفع شر عدوهم، الذي يريد أن يقتطعهم عنها ويحول بينهم وبينها، ويريد أن يجعلهم من حزبه ليكونوا من أصحاب السعير، والوسواس كما يكون من الجن يكون من الإنس، ولهذا قال: { مِنَ الْجِنَّةِ وَالنَّاسِ } . والحمد لله رب العالمين أولًا وآخرًا، وظاهرًا وباطنًا.ونسأله تعالى أن يتم نعمته، وأن يعفو عنا ذنوبًا لنا حالت بيننا وبين كثير من بركاته، وخطايا وشهوات ذهبت بقلوبنا عن تدبر آياته.ونرجوه ونأمل منه أن لا يحرمنا خير ما عنده بشر ما عندنا، فإنه لا ييأس من روح الله إلا القوم الكافرون، ولا يقنط من رحمته إلا القوم الضالون.وصلى الله وسلم على رسوله محمد وعلى آله وصحبه أجمعين، صلاة وسلامًا دائمين متواصلين أبد الأوقات، والحمد لله الذي بنعمته تتم الصالحات.تم تفسير كتاب الله بعونه وحسن توفيقه، على يد جامعه وكاتبه، عبد الرحمن بن ناصر بن عبد الله المعروف بابن سعدي، غفر الله له ولوالديه وجميع المسلمين، وذلك في غرة ربيع الأول من سنة أربع وأربعين وثلثمائة وألف من هجرة محمدً صلى الله عليه وسلم تم بحمد الله لاتنسونا من دعوه بظهر الغيب"}};
